(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-069"]={"sura":69,"name_ar":"الحاقة","name_en":"Al-Haqqah","verses":52,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":52,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=12\" class=\"link\">69:12</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:12 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=12\" class=\"link\">69:12</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:12 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=12\" class=\"link\">69:12</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:12 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=12\" class=\"link\">69:12</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:12 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=12\" class=\"link\">69:12</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:12 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=12\" class=\"link\">69:12</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:12 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=12\" class=\"link\">69:12</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:12 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=12\" class=\"link\">69:12</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:12 ஐ பார்க்கவும்"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=12\" class=\"link\">69:12</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:12 ஐ பார்க்கவும்"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=12\" class=\"link\">69:12</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:12 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=12\" class=\"link\">69:12</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:12 ஐ பார்க்கவும்"},"12":{"html":"<strong>மக்காவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>மறுமை நாளின் மகத்துவம் குறித்த எச்சரிக்கை</strong><br />\r\n<br />\r\nஅல்-ஹாக்கா (நிச்சயமாக நிகழக்கூடியது) என்பது மறுமை நாளின் பெயர்களில் ஒன்றாகும். ஏனெனில், அந்நாளில் வாக்குறுதிகளும் எச்சரிக்கைகளும் நிச்சயமாக நிறைவேறும். இதன் காரணமாகவே அல்லாஹ் இந்த விஷயத்தின் மகத்துவத்தைப் பிரகடனப்படுத்துகிறான். அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَدْرَاكَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">الْحَاقَّةُ</span><br />\r\n<br />\r\n(அல்-ஹாக்கா என்றால் என்னவென்று உமக்குத் தெரியப்படுத்துவது எது?)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذَّبَتْ</span> <span class=\"quran-arabic-font text-success\">ثَمُودُ</span> <span class=\"quran-arabic-font text-success\">وَعَادٌ</span> <span class=\"quran-arabic-font text-success\">بِالْقَارِعَةِ</span><br />\r\n<br />\r\n(ஸமூத் மற்றும் ஆத் கூட்டத்தார் (திடுக்கிடச் செய்யும்) காரிஆவைப் பொய்ப்பித்தனர்.)<br />\r\n<br />\r\n<strong>சமூகங்களின் அழிவைப் பற்றிய குறிப்பு</strong><br />\r\n<br />\r\nபிறகு, உயிர்த்தெழுதலை மறுத்த சமூகங்கள் அழிக்கப்பட்டதைப் பற்றி அல்லாஹ் குறிப்பிடுகிறான். அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَمَّا</span> <span class=\"quran-arabic-font text-success\">ثَمُودُ</span> <span class=\"quran-arabic-font text-success\">فَأُهْلِكُواْ</span> <span class=\"quran-arabic-font text-success\">بِالطَّاغِيَةِ</span><br />\r\n<br />\r\n(ஸமூத் கூட்டத்தாரைப் பொறுத்தவரை, அவர்கள் 'தாகியா'வினால் (எல்லை மீறிய சப்தத்தினால்) அழிக்கப்பட்டனர்!) அது அவர்களைச் செயலிழக்கச் செய்த ஒரு பெரும் சப்தம் மற்றும் நிலநடுக்கமாகும். கதாதா (ரழி) அவர்கள் இதைப் போன்றே, \"'அத்-தாகியா' என்பது பெரும் சப்தமாகும்\" என்று கூறினார்கள். முஜாஹித் (ரழி) அவர்கள், \"'அத்-தாகியா' என்பது பாவங்களைக் குறிக்கும்\" என்று கூறினார்கள். அர்-ரபீஃ பின் அனஸ் (ரழி) அவர்களும் இப்னு ஸைத் (ரழி) அவர்களும் இதையே கூறினார்கள்; வரம்பு மீறுதல் என்பதே இதன் பொருள் என்று அவர்கள் விளக்கமளித்தனர். இதைக் குறிப்பிட்ட பிறகு, இப்னு ஸைத் (ரழி) அவர்கள் தனது கூற்றுக்கு ஆதாரமாகப் பின்வரும் வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذَّبَتْ</span> <span class=\"quran-arabic-font text-success\">ثَمُودُ</span> <span class=\"quran-arabic-font text-success\">بِطَغْوَاهَآ</span><br />\r\n<br />\r\n(ஸமூத் கூட்டத்தினர் தமது வரம்பு மீறலால் பொய்ப்பித்தனர்.) பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">عَادٌ</span> <span class=\"quran-arabic-font text-success\">فَأُهْلِكُواْ</span> <span class=\"quran-arabic-font text-success\">بِرِيحٍ</span> <span class=\"quran-arabic-font text-success\">صَرْصَرٍ</span> <span class=\"quran-arabic-font text-success\">عَاتِيَةٍ</span><br />\r\n<br />\r\n(ஆத் கூட்டத்தாரைப் பொறுத்தவரை, அவர்கள் 'ஸர்ஸர்' எனும் கடும் , சீறிப் பாயும் காற்றால் அழிக்கப்பட்டனர்.) அதாவது, ஒரு கடும் குளிர்காற்று. கதாதா (ரழி), அஸ்-ஸுத்தீ (ரழி), அர்-ரபீஃ பின் அனஸ் (ரழி) மற்றும் அத்-தவ்ரீ (ரழி) ஆகியோர் பின்வரும் வசனத்தைப் பற்றி கூறுகையில்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَاتِيَةٍ</span><br />\r\n<br />\r\n('ஆத்தியா') \"இதன் பொருள் காற்றின் மிகக் கடுமையான வீசுதல்\" என்று கூறினர். கதாதா (ரழி) அவர்கள், \"அது அவர்களின் இதயங்களைத் துளைக்கும் வரை அவர்கள் மீது மிகத் தீவிரமாக வீசியது\" என்று கூறினார்கள். அத்-தஹ்ஹாக் (ரழி) அவர்கள் கூறுகையில்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">صَرْصَرٍ</span><br />\r\n<br />\r\n('ஸர்ஸர்') \"இதன் பொருள் கடும் குளிர்; மேலும்<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَاتِيَةٍ</span><br />\r\n<br />\r\n('ஆத்தியா') என்றால், அது எந்தவிதக் கருணையோ அல்லது அருளோ இன்றி அவர்கள் மீது சீறிப் பாய்ந்தது\" என்று விளக்கமளித்தார்கள். அலீ (ரழி) அவர்களும் மற்றவர்களும், \"அவர்களுடைய சேமித்து வைக்கப்பட்டிருந்த அறுவடைப் பொருட்கள் பாழாகும் வரை அது கடுமையாக வீசியது\" என்று கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَخَّرَهَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span><br />\r\n<br />\r\n(அதனை அல்லாஹ் அவர்கள் மீது ஏவினான்.) அதாவது, அந்தப் பெரும் காற்று அவர்களை மிகைக்கும்படிச் செய்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَبْعَ</span> <span class=\"quran-arabic-font text-success\">لَيَالٍ</span> <span class=\"quran-arabic-font text-success\">وَثَمَانِيَةَ</span> <span class=\"quran-arabic-font text-success\">أَيَّامٍ</span> <span class=\"quran-arabic-font text-success\">حُسُوماً</span><br />\r\n<br />\r\n(ஏழு இரவுகளும் எட்டுப் பகல்களும் 'ஹுஸூம்' ஆக,) 'ஹுஸூம்' என்றால் முழுமையான, இடைவிடாத மற்றும் தீய விளைவுகளைக் கொண்ட தொடர்ச்சி என்று பொருள். இப்னு மஸ்ஊத் (ரழி), இப்னு அப்பாஸ் (ரழி), முஜாஹித் (ரழி), இக்ரிமா (ரழி), அத்-தவ்ரீ (ரழி) மற்றும் பலர் \"'ஹுஸூம்' என்றால் தொடர்ச்சியாக\" என்று கூறினார்கள். இக்ரிமா (ரழி) அவர்களும் அர்-ரபீஃ பின் குதைம் (ரழி) அவர்களும், \"அது அவர்கள் மீது பெரும் கேடாக அமைந்தது என்பதே இதன் பொருள்\" என்று கூறியதாக அறிவிக்கப்பட்டுள்ளது. இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أَيَّامٍ</span> <span class=\"quran-arabic-font text-success\">نَّحِسَاتٍ</span><br />\r\n<br />\r\n(துரதிர்ஷ்டவசமான நாட்களில்) (41: 16). மக்கள் இப்போது 'அஃஜாஸ்' (A'jaz - வேரோடு அழித்தல்) என்று அழைப்பது இதைத்தான் என்று கூறப்படுகிறது. மக்கள் இந்த வார்த்தையை அல்லாஹ்வின் பின்வரும் வசனத்திலிருந்து எடுத்ததாகத் தெரிகிறது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَتَرَى</span> <span class=\"quran-arabic-font text-success\">الْقَوْمَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">صَرْعَى</span> <span class=\"quran-arabic-font text-success\">كَأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">أَعْجَازُ</span> <span class=\"quran-arabic-font text-success\">نَخْلٍ</span> <span class=\"quran-arabic-font text-success\">خَاوِيَةٍ</span><br />\r\n<br />\r\n(அதனால், அந்த மக்கள் வேரோடு சாய்ந்த பேரீச்சை மரத்தின் 'அஃஜாஸ்' (அடிமரங்கள்) போல் வீழ்ந்து கிடப்பதை நீர் காண்பீர், 'காவியா'!) இப்னு அப்பாஸ் (ரழி) அவர்கள் இதைப் பற்றி கூறுகையில்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">خَاوِيَةٍ</span><br />\r\n<br />\r\n('காவியா') \"இதன் பொருள் பாழடைந்தது\" என்று விளக்கினார்கள். பிற அறிஞர்கள், \"இதன் பொருள் சிதைந்து போனது\" என்று கூறினார்கள். அதாவது, அந்தக் காற்று அவர்களைப் பேரீச்சை மரங்களைப் போல் தரையில் மோதச் செய்தது; அவர்கள் தலைகீழாக விழுந்து உயிரிழந்தனர். அவர்களின் தலைகள் சிதறி, கிளைகளற்ற, அசைவற்ற, வெறும் உடல்களாக அவர்கள் கிடந்தனர். 'ஸஹீஹைன்' (புகாரி, முஸ்லிம்) நூல்களில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாக உறுதிப்படுத்தப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">نُصِرْتُ</span> <span class=\"quran-arabic-font text-success\">بِالصَّبَا</span> <span class=\"quran-arabic-font text-success\">وَأُهْلِكَتْ</span> <span class=\"quran-arabic-font text-success\">عَادٌ</span> <span class=\"quran-arabic-font text-success\">بِالدَّبُور</span>»<br />\r\n<br />\r\n(எனக்குக் கீழைக் காற்றின் (ஸபா) மூலம் உதவி செய்யப்பட்டது; ஆத் கூட்டத்தினர் மேற்குக் காற்றின் (தபூர்) மூலம் அழிக்கப்பட்டனர்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">لَهُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">بَاقِيَةٍ</span><br />\r\n<br />\r\n(அவர்களில் எஞ்சிய எவரையும் நீர் காண்கிறீரா?) அதாவது, 'அவர்களில் எவரேனும் எஞ்சியிருப்பதையோ அல்லது அவர்களிலிருந்து வந்தவர் என்று தன்னைக் கூறிக்கொள்ளும் எவரையேனும் நீர் காண்கிறீரா?' இல்லை, அவர்கள் அனைவரும் கடைசி ஆள் வரை அழிந்துவிட்டனர். அல்லாஹ் அவர்களுக்கு எந்த வாரிசுகளையும் மிஞ்ச வைக்கவில்லை. பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَآءَ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنُ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">قَبْلَهُ</span><br />\r\n<br />\r\n(ஃபிர்அவ்னும், அவனுக்கு முன் இருந்தவர்களும் வந்தனர்.) இது 'கப்லஹு' (Qablahu) என்ற வார்த்தையில் உள்ள 'காஃப்' எழுத்தின் கீழ் கஸ்ராவுடன் (கிப்லஹு - Qiblahu என) ஓதப்பட்டுள்ளது; இதற்கு 'அவனது காலத்தில் அவனுடன் இருந்தவர்கள்' என்று பொருள். அவர்கள் அவனைப் பின்பற்றிய நிராகரிப்பாளர்களான கிப்தி (Coptic) மக்கள் ஆவர். பிறர் அதனை 'காஃப்' எழுத்தின் மேல் ஃபத்ஹாவுடன் (கப்லஹு) ஓதினர்; இதற்கு 'அவனுக்கு முன் வாழ்ந்த அவனையொத்த சமூகங்கள்' என்று பொருள். அல்லாஹ்வின் கூற்றான:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالْمُؤْتَفِكَاتُ</span><br />\r\n<br />\r\n(தலைகீழாகப் புரட்டப்பட்ட நகரங்கள்) என்பது தங்கள் தூதர்களை நிராகரித்த அந்த சமூகங்களைக் குறிக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِالْخَاطِئَةِ</span><br />\r\n<br />\r\n('அல்-காத்திஆ'வைச் செய்தனர்.) 'அல்-காத்திஆ' என்பது அல்லாஹ் அருளிய வஹீயை (இறைச்செய்தியை) அவர்கள் நிராகரித்ததைக் குறிக்கும். அர்-ரபீஃ (ரழி) அவர்கள் கூறுகையில்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِالْخَاطِئَةِ</span><br />\r\n<br />\r\n('அல்-காத்திஆ'வைச் செய்தனர்.) \"இதன் பொருள் கீழ்ப்படியாமை\" என்று விளக்கினார்கள். முஜாஹித் (ரழி) அவர்கள், \"அவர்கள் தவறுகள் செய்தனர்\" என்று கூறினார்கள். எனவே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَعَصَوْاْ</span> <span class=\"quran-arabic-font text-success\">رَسُولَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span><br />\r\n<br />\r\n(மேலும் அவர்கள் தங்கள் இறைவனின் தூதருக்கு மாறுசெய்தனர்,) அதாவது அவர்கள் அனைவரும் ஒரே மனநிலை கொண்டவர்கள்; தங்களுக்கு அனுப்பப்பட்ட அல்லாஹ்வின் தூதரை (ஸல்) அவர்கள் அனைவரும் பொய்ப்பித்தனர். அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كُلٌّ</span> <span class=\"quran-arabic-font text-success\">كَذَّبَ</span> <span class=\"quran-arabic-font text-success\">الرُّسُلَ</span> <span class=\"quran-arabic-font text-success\">فَحَقَّ</span> <span class=\"quran-arabic-font text-success\">وَعِيدِ</span><br />\r\n<br />\r\n(அவர்கள் ஒவ்வொருவரும் தூதர்களைப் பொய்யாக்கினர், எனவே எனது எச்சரிக்கை உறுதியானது.) எனவே, எவர் ஒரு தூதரை மறுக்கிறாரோ, அவர் நிச்சயமாக அனைத்துத் தூதர்களையும் மறுத்தவர் ஆவார். இதனை அல்லாஹ் பின்வருமாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذَّبَتْ</span> <span class=\"quran-arabic-font text-success\">قَوْمُ</span> <span class=\"quran-arabic-font text-success\">نُوحٍ</span> <span class=\"quran-arabic-font text-success\">الْمُرْسَلِينَ</span><br />\r\n<br />\r\n(நூஹ் (அலை) அவர்களின் சமூகம் தூதர்களைப் பொய்யாக்கியது.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذَّبَتْ</span> <span class=\"quran-arabic-font text-success\">عَادٌ</span> <span class=\"quran-arabic-font text-success\">الْمُرْسَلِينَ</span><br />\r\n<br />\r\n(ஆத் கூட்டத்தினர் தூதர்களைப் பொய்யாக்கினர்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذَّبَتْ</span> <span class=\"quran-arabic-font text-success\">ثَمُودُ</span> <span class=\"quran-arabic-font text-success\">الْمُرْسَلِينَ</span><br />\r\n<br />\r\n(ஸமூத் கூட்டத்தினர் தூதர்களைப் பொய்யாக்கினர்.) எனினும், ஒவ்வொரு சமூகத்திற்கும் ஒரே ஒரு தூதரே அனுப்பப்பட்டார். எனவே, அல்லாஹ் இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَعَصَوْاْ</span> <span class=\"quran-arabic-font text-success\">رَسُولَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">فَأَخَذَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَخْذَةً</span> <span class=\"quran-arabic-font text-success\">رَّابِيَةً</span><br />\r\n<br />\r\n(மேலும் அவர்கள் தங்கள் இறைவனின் தூதருக்கு மாறுசெய்தனர், எனவே அவன் அவர்களை 'ராபியா' எனும் தண்டனையால் பிடித்தான்.) 'ராபியா' என்றால் மிகப் பெரிய, கடுமையான மற்றும் வேதனையானது என்று பொருள். முஜாஹித் (ரழி) அவர்கள் \"'ராபியா' என்றால் கடுமையானது\" என்றும், அஸ்-ஸுத்தீ (ரழி) அவர்கள் \"இதன் பொருள் அழிவுகரமானது\" என்றும் கூறினார்கள்.<br />\r\n<br />\r\n<strong>கப்பல் எனும் அருளைப் பற்றிய ஒரு நினைவூட்டல்</strong><br />\r\n<br />\r\nபின்னர், அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">لَمَّا</span> <span class=\"quran-arabic-font text-success\">طَغَا</span> <span class=\"quran-arabic-font text-success\">الْمَآءُ</span><br />\r\n<br />\r\n(நிச்சயமாக, நீர் அதன் எல்லையைத் தாண்டியபோது,) அதாவது, அல்லாஹ்வின் கட்டளையால் தண்ணீர் கரைகளைத் தாண்டி உயர்ந்து, இருந்த அனைத்தையும் மூழ்கடித்தது. இப்னு அப்பாஸ் (ரழி) அவர்களும் பிறரும், \"தண்ணீர் அதன் எல்லையைத் தாண்டுவது என்பது அது பெருமளவில் அதிகரிப்பதைக் குறிக்கும்\" என்று கூறினர். நூஹ் (அலை) அவர்களை அவரது மக்கள் பொய்ப்பித்து, எதிர்த்து, அல்லாஹ் அல்லாதவர்களை வணங்கியபோது அவர்களுக்கு எதிராக அவர் செய்த பிரார்த்தனையால் இது நிகழ்ந்தது. அல்லாஹ் அவரது பிரார்த்தனையை ஏற்றுக்கொண்டான்; நூஹ் (அலை) அவர்களுடன் கப்பலில் இருந்தவர்களைத் தவிர பூமியில் இருந்த அனைவரும் வெள்ளத்தில் மூழ்கடிக்கப்பட்டனர். எனவே, இன்றுள்ள மனிதர்கள் அனைவரும் நூஹ் (அலை) அவர்களின் சந்ததியினரே ஆவர். இந்த அருளை அல்லாஹ் மனிதகுலத்திற்கு நினைவூட்டுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">لَمَّا</span> <span class=\"quran-arabic-font text-success\">طَغَا</span> <span class=\"quran-arabic-font text-success\">الْمَآءُ</span> <span class=\"quran-arabic-font text-success\">حَمَلْنَاكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْجَارِيَةِ</span><br />\r\n<br />\r\n(நிச்சயமாக, நீர் அதன் எல்லையைத் தாண்டியபோது, நாம் உங்களைக் கப்பலில் சுமந்தோம்.) அதாவது, நீரின் மேற்பரப்பில் மிதந்து செல்லும் ஒரு கப்பலில்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِنَجْعَلَهَا</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">تَذْكِرَةً</span><br />\r\n<br />\r\n(அதனை நாம் உங்களுக்கு ஒரு நினைவூட்டலாக ஆக்குவதற்காக) இங்கு \"அது\" என்ற சொல் கப்பல்களின் வகையைக் குறிக்கிறது. 'அத்தகைய ஒரு படைப்பை (கப்பல்களை) நாம் உங்களுக்காக நிலைக்கச் செய்தோம்; அதன் மூலம் நீங்கள் கடல்களில் பயணம் செய்கிறீர்கள்' என்பதே இதன் பொருள். இது அல்லாஹ் பின்வரும் வசனங்களில் கூறுவது போல் உள்ளது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْفُلْكِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَنْعَامِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَرْكَبُونَلِتَسْتَوُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ظُهُورِهِ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">تَذْكُرُواْ</span> <span class=\"quran-arabic-font text-success\">نِعْمَةَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكُمْ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">اسْتَوَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span><br />\r\n<br />\r\n(மேலும் உங்களுக்காகக் கப்பல்களையும், நீங்கள் சவாரி செய்யும் கால்நடைகளையும் அவன் ஏற்படுத்தியுள்ளான். அவற்றின் முதுகுகளில் நீங்கள் ஏறுவதற்காகவும், அதன் மீது நீங்கள் ஏறியதும் உங்கள் இறைவனின் அருளை நினைவுகூர்வதற்காகவும்) (<a href=\"qurandisp.php?sura=43&ayah=12\" class=\"link\">43:12</a>,13). மேலும் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَءَايَةٌ</span> <span class=\"quran-arabic-font text-success\">لَّهُمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّا</span> <span class=\"quran-arabic-font text-success\">حَمَلْنَا</span> <span class=\"quran-arabic-font text-success\">ذُرِّيَّتَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْفُلْكِ</span> <span class=\"quran-arabic-font text-success\">الْمَشْحُونِ</span> - <span class=\"quran-arabic-font text-success\">وَخَلَقْنَا</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">مِّثْلِهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَرْكَبُونَ</span><br />\r\n<br />\r\n(மேலும், அவர்களுக்கு ஓர் அத்தாட்சி என்னவென்றால், நாம் அவர்களின் சந்ததியினரை நிரப்பப்பட்ட கப்பலில் சுமந்து சென்றோம். மேலும், அதைப் போன்றே அவர்கள் சவாரி செய்வதற்காக நாம் அவர்களுக்காகப் படைத்துள்ளோம்.) (<a href=\"qurandisp.php?sura=36&ayah=41\" class=\"link\">36:41</a>,42). கதாதா (ரழி) அவர்கள் கூறுகையில், \"இந்த உம்மத்தின் முதல் தலைமுறையினர் அக்கப்பலைப் பார்க்கும் வரை அல்லாஹ் அதனை நிலைக்கச் செய்தான்\" என்றார்கள். எனினும், இது பொதுவாக அனைத்துக் கப்பல்களையும் குறிக்கும் என்ற முதல் கருத்தே மிகவும் பொருத்தமானது. அல்லாஹ் தொடர்ந்து கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَعِيَهَآ</span> <span class=\"quran-arabic-font text-success\">أُذُنٌ</span> <span class=\"quran-arabic-font text-success\">وَعِيَةٌ</span><br />\r\n<br />\r\n(மேலும் அதனை நினைவில் கொள்ளும் காதுகள் கிரகித்துக் கொள்வதற்காக.) அதாவது, உள்வாங்கும் திறன் கொண்ட காதுகள் இந்த அருளைப் புரிந்து சிந்திப்பதற்காக. இப்னு அப்பாஸ் (ரழி) அவர்கள், \"இதன் பொருள் நினைவில் வைத்துக் கொள்ளும் மற்றும் கேட்கும் திறன் கொண்ட காது\" என்று கூறினார். கதாதா (ரழி) அவர்கள் கூறுகையில்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُذُنٌ</span> <span class=\"quran-arabic-font text-success\">وَعِيَةٌ</span><br />\r\n<br />\r\n(நினைவில் கொள்ளும் காதுகளால்.) \"அல்லாஹ் நுண்ணறிவை வழங்கிய காது; அது அல்லாஹ்வின் வேதத்தைக் கேட்டுப் பயனடைகிறது\" என்று விளக்கினார்கள். அத்-தஹ்ஹாக் (ரழி) அவர்கள் கூறுகையில்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَعِيَهَآ</span> <span class=\"quran-arabic-font text-success\">أُذُنٌ</span> <span class=\"quran-arabic-font text-success\">وَعِيَةٌ</span><br />\r\n<br />\r\n(மேலும் அதை நினைவில் கொள்ளும் காதுகள் நினைவில் வைத்துக் கொள்வதற்காக.) (<a href=\"qurandisp.php?sura=69&ayah=12\" class=\"link\">69:12</a>) \"அதனைக் கேட்டு நினைவில் கொள்ளும் காது, அதாவது ஆரோக்கியமான செவித்திறனும் சரியான புத்தியும் கொண்ட நபர்\" என்று விளக்கினார்கள். இது இறைவசனங்களைப் புரிந்து உள்வாங்கிக் கொள்ளும் அனைவரையும் குறிக்கும் பொதுவான கருத்தாகும்.<br />\r\n<br />","text":"மக்காவில் அருளப்பட்டது\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nமறுமை நாளின் மகத்துவம் குறித்த எச்சரிக்கை\n\r\n\n\r\nஅல்-ஹாக்கா (நிச்சயமாக நிகழக்கூடியது) என்பது மறுமை நாளின் பெயர்களில் ஒன்றாகும். ஏனெனில், அந்நாளில் வாக்குறுதிகளும் எச்சரிக்கைகளும் நிச்சயமாக நிறைவேறும். இதன் காரணமாகவே அல்லாஹ் இந்த விஷயத்தின் மகத்துவத்தைப் பிரகடனப்படுத்துகிறான். அவன் கூறுகிறான்:\n\r\n\n\r\nوَمَآ أَدْرَاكَ مَا الْحَاقَّةُ\n\r\n\n\r\n(அல்-ஹாக்கா என்றால் என்னவென்று உமக்குத் தெரியப்படுத்துவது எது?)\n\r\n\n\r\nكَذَّبَتْ ثَمُودُ وَعَادٌ بِالْقَارِعَةِ\n\r\n\n\r\n(ஸமூத் மற்றும் ஆத் கூட்டத்தார் (திடுக்கிடச் செய்யும்) காரிஆவைப் பொய்ப்பித்தனர்.)\n\r\n\n\r\nசமூகங்களின் அழிவைப் பற்றிய குறிப்பு\n\r\n\n\r\nபிறகு, உயிர்த்தெழுதலை மறுத்த சமூகங்கள் அழிக்கப்பட்டதைப் பற்றி அல்லாஹ் குறிப்பிடுகிறான். அவன் கூறுகிறான்:\n\r\n\n\r\nفَأَمَّا ثَمُودُ فَأُهْلِكُواْ بِالطَّاغِيَةِ\n\r\n\n\r\n(ஸமூத் கூட்டத்தாரைப் பொறுத்தவரை, அவர்கள் 'தாகியா'வினால் (எல்லை மீறிய சப்தத்தினால்) அழிக்கப்பட்டனர்!) அது அவர்களைச் செயலிழக்கச் செய்த ஒரு பெரும் சப்தம் மற்றும் நிலநடுக்கமாகும். கதாதா (ரழி) அவர்கள் இதைப் போன்றே, \"'அத்-தாகியா' என்பது பெரும் சப்தமாகும்\" என்று கூறினார்கள். முஜாஹித் (ரழி) அவர்கள், \"'அத்-தாகியா' என்பது பாவங்களைக் குறிக்கும்\" என்று கூறினார்கள். அர்-ரபீஃ பின் அனஸ் (ரழி) அவர்களும் இப்னு ஸைத் (ரழி) அவர்களும் இதையே கூறினார்கள்; வரம்பு மீறுதல் என்பதே இதன் பொருள் என்று அவர்கள் விளக்கமளித்தனர். இதைக் குறிப்பிட்ட பிறகு, இப்னு ஸைத் (ரழி) அவர்கள் தனது கூற்றுக்கு ஆதாரமாகப் பின்வரும் வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nكَذَّبَتْ ثَمُودُ بِطَغْوَاهَآ\n\r\n\n\r\n(ஸமூத் கூட்டத்தினர் தமது வரம்பு மீறலால் பொய்ப்பித்தனர்.) பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَأَمَّا عَادٌ فَأُهْلِكُواْ بِرِيحٍ صَرْصَرٍ عَاتِيَةٍ\n\r\n\n\r\n(ஆத் கூட்டத்தாரைப் பொறுத்தவரை, அவர்கள் 'ஸர்ஸர்' எனும் கடும் , சீறிப் பாயும் காற்றால் அழிக்கப்பட்டனர்.) அதாவது, ஒரு கடும் குளிர்காற்று. கதாதா (ரழி), அஸ்-ஸுத்தீ (ரழி), அர்-ரபீஃ பின் அனஸ் (ரழி) மற்றும் அத்-தவ்ரீ (ரழி) ஆகியோர் பின்வரும் வசனத்தைப் பற்றி கூறுகையில்:\n\r\n\n\r\nعَاتِيَةٍ\n\r\n\n\r\n('ஆத்தியா') \"இதன் பொருள் காற்றின் மிகக் கடுமையான வீசுதல்\" என்று கூறினர். கதாதா (ரழி) அவர்கள், \"அது அவர்களின் இதயங்களைத் துளைக்கும் வரை அவர்கள் மீது மிகத் தீவிரமாக வீசியது\" என்று கூறினார்கள். அத்-தஹ்ஹாக் (ரழி) அவர்கள் கூறுகையில்:\n\r\n\n\r\nصَرْصَرٍ\n\r\n\n\r\n('ஸர்ஸர்') \"இதன் பொருள் கடும் குளிர்; மேலும்\n\r\n\n\r\nعَاتِيَةٍ\n\r\n\n\r\n('ஆத்தியா') என்றால், அது எந்தவிதக் கருணையோ அல்லது அருளோ இன்றி அவர்கள் மீது சீறிப் பாய்ந்தது\" என்று விளக்கமளித்தார்கள். அலீ (ரழி) அவர்களும் மற்றவர்களும், \"அவர்களுடைய சேமித்து வைக்கப்பட்டிருந்த அறுவடைப் பொருட்கள் பாழாகும் வரை அது கடுமையாக வீசியது\" என்று கூறினார்கள்.\n\r\n\n\r\nسَخَّرَهَا عَلَيْهِمْ\n\r\n\n\r\n(அதனை அல்லாஹ் அவர்கள் மீது ஏவினான்.) அதாவது, அந்தப் பெரும் காற்று அவர்களை மிகைக்கும்படிச் செய்தான்.\n\r\n\n\r\nسَبْعَ لَيَالٍ وَثَمَانِيَةَ أَيَّامٍ حُسُوماً\n\r\n\n\r\n(ஏழு இரவுகளும் எட்டுப் பகல்களும் 'ஹுஸூம்' ஆக,) 'ஹுஸூம்' என்றால் முழுமையான, இடைவிடாத மற்றும் தீய விளைவுகளைக் கொண்ட தொடர்ச்சி என்று பொருள். இப்னு மஸ்ஊத் (ரழி), இப்னு அப்பாஸ் (ரழி), முஜாஹித் (ரழி), இக்ரிமா (ரழி), அத்-தவ்ரீ (ரழி) மற்றும் பலர் \"'ஹுஸூம்' என்றால் தொடர்ச்சியாக\" என்று கூறினார்கள். இக்ரிமா (ரழி) அவர்களும் அர்-ரபீஃ பின் குதைம் (ரழி) அவர்களும், \"அது அவர்கள் மீது பெரும் கேடாக அமைந்தது என்பதே இதன் பொருள்\" என்று கூறியதாக அறிவிக்கப்பட்டுள்ளது. இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றது:\n\r\n\n\r\nفِى أَيَّامٍ نَّحِسَاتٍ\n\r\n\n\r\n(துரதிர்ஷ்டவசமான நாட்களில்) (41: 16). மக்கள் இப்போது 'அஃஜாஸ்' (A'jaz - வேரோடு அழித்தல்) என்று அழைப்பது இதைத்தான் என்று கூறப்படுகிறது. மக்கள் இந்த வார்த்தையை அல்லாஹ்வின் பின்வரும் வசனத்திலிருந்து எடுத்ததாகத் தெரிகிறது:\n\r\n\n\r\nفَتَرَى الْقَوْمَ فِيهَا صَرْعَى كَأَنَّهُمْ أَعْجَازُ نَخْلٍ خَاوِيَةٍ\n\r\n\n\r\n(அதனால், அந்த மக்கள் வேரோடு சாய்ந்த பேரீச்சை மரத்தின் 'அஃஜாஸ்' (அடிமரங்கள்) போல் வீழ்ந்து கிடப்பதை நீர் காண்பீர், 'காவியா'!) இப்னு அப்பாஸ் (ரழி) அவர்கள் இதைப் பற்றி கூறுகையில்:\n\r\n\n\r\nخَاوِيَةٍ\n\r\n\n\r\n('காவியா') \"இதன் பொருள் பாழடைந்தது\" என்று விளக்கினார்கள். பிற அறிஞர்கள், \"இதன் பொருள் சிதைந்து போனது\" என்று கூறினார்கள். அதாவது, அந்தக் காற்று அவர்களைப் பேரீச்சை மரங்களைப் போல் தரையில் மோதச் செய்தது; அவர்கள் தலைகீழாக விழுந்து உயிரிழந்தனர். அவர்களின் தலைகள் சிதறி, கிளைகளற்ற, அசைவற்ற, வெறும் உடல்களாக அவர்கள் கிடந்தனர். 'ஸஹீஹைன்' (புகாரி, முஸ்லிம்) நூல்களில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாக உறுதிப்படுத்தப்பட்டுள்ளது:\n\r\n\n\r\n«نُصِرْتُ بِالصَّبَا وَأُهْلِكَتْ عَادٌ بِالدَّبُور»\n\r\n\n\r\n(எனக்குக் கீழைக் காற்றின் (ஸபா) மூலம் உதவி செய்யப்பட்டது; ஆத் கூட்டத்தினர் மேற்குக் காற்றின் (தபூர்) மூலம் அழிக்கப்பட்டனர்.)\n\r\n\n\r\nفَهَلْ تَرَى لَهُم مِّن بَاقِيَةٍ\n\r\n\n\r\n(அவர்களில் எஞ்சிய எவரையும் நீர் காண்கிறீரா?) அதாவது, 'அவர்களில் எவரேனும் எஞ்சியிருப்பதையோ அல்லது அவர்களிலிருந்து வந்தவர் என்று தன்னைக் கூறிக்கொள்ளும் எவரையேனும் நீர் காண்கிறீரா?' இல்லை, அவர்கள் அனைவரும் கடைசி ஆள் வரை அழிந்துவிட்டனர். அல்லாஹ் அவர்களுக்கு எந்த வாரிசுகளையும் மிஞ்ச வைக்கவில்லை. பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَجَآءَ فِرْعَوْنُ وَمَن قَبْلَهُ\n\r\n\n\r\n(ஃபிர்அவ்னும், அவனுக்கு முன் இருந்தவர்களும் வந்தனர்.) இது 'கப்லஹு' (Qablahu) என்ற வார்த்தையில் உள்ள 'காஃப்' எழுத்தின் கீழ் கஸ்ராவுடன் (கிப்லஹு - Qiblahu என) ஓதப்பட்டுள்ளது; இதற்கு 'அவனது காலத்தில் அவனுடன் இருந்தவர்கள்' என்று பொருள். அவர்கள் அவனைப் பின்பற்றிய நிராகரிப்பாளர்களான கிப்தி (Coptic) மக்கள் ஆவர். பிறர் அதனை 'காஃப்' எழுத்தின் மேல் ஃபத்ஹாவுடன் (கப்லஹு) ஓதினர்; இதற்கு 'அவனுக்கு முன் வாழ்ந்த அவனையொத்த சமூகங்கள்' என்று பொருள். அல்லாஹ்வின் கூற்றான:\n\r\n\n\r\nوَالْمُؤْتَفِكَاتُ\n\r\n\n\r\n(தலைகீழாகப் புரட்டப்பட்ட நகரங்கள்) என்பது தங்கள் தூதர்களை நிராகரித்த அந்த சமூகங்களைக் குறிக்கும்.\n\r\n\n\r\nبِالْخَاطِئَةِ\n\r\n\n\r\n('அல்-காத்திஆ'வைச் செய்தனர்.) 'அல்-காத்திஆ' என்பது அல்லாஹ் அருளிய வஹீயை (இறைச்செய்தியை) அவர்கள் நிராகரித்ததைக் குறிக்கும். அர்-ரபீஃ (ரழி) அவர்கள் கூறுகையில்:\n\r\n\n\r\nبِالْخَاطِئَةِ\n\r\n\n\r\n('அல்-காத்திஆ'வைச் செய்தனர்.) \"இதன் பொருள் கீழ்ப்படியாமை\" என்று விளக்கினார்கள். முஜாஹித் (ரழி) அவர்கள், \"அவர்கள் தவறுகள் செய்தனர்\" என்று கூறினார்கள். எனவே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَعَصَوْاْ رَسُولَ رَبِّهِمْ\n\r\n\n\r\n(மேலும் அவர்கள் தங்கள் இறைவனின் தூதருக்கு மாறுசெய்தனர்,) அதாவது அவர்கள் அனைவரும் ஒரே மனநிலை கொண்டவர்கள்; தங்களுக்கு அனுப்பப்பட்ட அல்லாஹ்வின் தூதரை (ஸல்) அவர்கள் அனைவரும் பொய்ப்பித்தனர். அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\nكُلٌّ كَذَّبَ الرُّسُلَ فَحَقَّ وَعِيدِ\n\r\n\n\r\n(அவர்கள் ஒவ்வொருவரும் தூதர்களைப் பொய்யாக்கினர், எனவே எனது எச்சரிக்கை உறுதியானது.) எனவே, எவர் ஒரு தூதரை மறுக்கிறாரோ, அவர் நிச்சயமாக அனைத்துத் தூதர்களையும் மறுத்தவர் ஆவார். இதனை அல்லாஹ் பின்வருமாறு கூறுகிறான்:\n\r\n\n\r\nكَذَّبَتْ قَوْمُ نُوحٍ الْمُرْسَلِينَ\n\r\n\n\r\n(நூஹ் (அலை) அவர்களின் சமூகம் தூதர்களைப் பொய்யாக்கியது.)\n\r\n\n\r\nكَذَّبَتْ عَادٌ الْمُرْسَلِينَ\n\r\n\n\r\n(ஆத் கூட்டத்தினர் தூதர்களைப் பொய்யாக்கினர்.)\n\r\n\n\r\nكَذَّبَتْ ثَمُودُ الْمُرْسَلِينَ\n\r\n\n\r\n(ஸமூத் கூட்டத்தினர் தூதர்களைப் பொய்யாக்கினர்.) எனினும், ஒவ்வொரு சமூகத்திற்கும் ஒரே ஒரு தூதரே அனுப்பப்பட்டார். எனவே, அல்லாஹ் இங்கே கூறுகிறான்:\n\r\n\n\r\nفَعَصَوْاْ رَسُولَ رَبِّهِمْ فَأَخَذَهُمْ أَخْذَةً رَّابِيَةً\n\r\n\n\r\n(மேலும் அவர்கள் தங்கள் இறைவனின் தூதருக்கு மாறுசெய்தனர், எனவே அவன் அவர்களை 'ராபியா' எனும் தண்டனையால் பிடித்தான்.) 'ராபியா' என்றால் மிகப் பெரிய, கடுமையான மற்றும் வேதனையானது என்று பொருள். முஜாஹித் (ரழி) அவர்கள் \"'ராபியா' என்றால் கடுமையானது\" என்றும், அஸ்-ஸுத்தீ (ரழி) அவர்கள் \"இதன் பொருள் அழிவுகரமானது\" என்றும் கூறினார்கள்.\n\r\n\n\r\nகப்பல் எனும் அருளைப் பற்றிய ஒரு நினைவூட்டல்\n\r\n\n\r\nபின்னர், அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِنَّا لَمَّا طَغَا الْمَآءُ\n\r\n\n\r\n(நிச்சயமாக, நீர் அதன் எல்லையைத் தாண்டியபோது,) அதாவது, அல்லாஹ்வின் கட்டளையால் தண்ணீர் கரைகளைத் தாண்டி உயர்ந்து, இருந்த அனைத்தையும் மூழ்கடித்தது. இப்னு அப்பாஸ் (ரழி) அவர்களும் பிறரும், \"தண்ணீர் அதன் எல்லையைத் தாண்டுவது என்பது அது பெருமளவில் அதிகரிப்பதைக் குறிக்கும்\" என்று கூறினர். நூஹ் (அலை) அவர்களை அவரது மக்கள் பொய்ப்பித்து, எதிர்த்து, அல்லாஹ் அல்லாதவர்களை வணங்கியபோது அவர்களுக்கு எதிராக அவர் செய்த பிரார்த்தனையால் இது நிகழ்ந்தது. அல்லாஹ் அவரது பிரார்த்தனையை ஏற்றுக்கொண்டான்; நூஹ் (அலை) அவர்களுடன் கப்பலில் இருந்தவர்களைத் தவிர பூமியில் இருந்த அனைவரும் வெள்ளத்தில் மூழ்கடிக்கப்பட்டனர். எனவே, இன்றுள்ள மனிதர்கள் அனைவரும் நூஹ் (அலை) அவர்களின் சந்ததியினரே ஆவர். இந்த அருளை அல்லாஹ் மனிதகுலத்திற்கு நினைவூட்டுகிறான்:\n\r\n\n\r\nإِنَّا لَمَّا طَغَا الْمَآءُ حَمَلْنَاكُمْ فِى الْجَارِيَةِ\n\r\n\n\r\n(நிச்சயமாக, நீர் அதன் எல்லையைத் தாண்டியபோது, நாம் உங்களைக் கப்பலில் சுமந்தோம்.) அதாவது, நீரின் மேற்பரப்பில் மிதந்து செல்லும் ஒரு கப்பலில்.\n\r\n\n\r\nلِنَجْعَلَهَا لَكُمْ تَذْكِرَةً\n\r\n\n\r\n(அதனை நாம் உங்களுக்கு ஒரு நினைவூட்டலாக ஆக்குவதற்காக) இங்கு \"அது\" என்ற சொல் கப்பல்களின் வகையைக் குறிக்கிறது. 'அத்தகைய ஒரு படைப்பை (கப்பல்களை) நாம் உங்களுக்காக நிலைக்கச் செய்தோம்; அதன் மூலம் நீங்கள் கடல்களில் பயணம் செய்கிறீர்கள்' என்பதே இதன் பொருள். இது அல்லாஹ் பின்வரும் வசனங்களில் கூறுவது போல் உள்ளது:\n\r\n\n\r\nوَجَعَلَ لَكُمْ مِّنَ الْفُلْكِ وَالْأَنْعَامِ مَا تَرْكَبُونَلِتَسْتَوُواْ عَلَى ظُهُورِهِ ثُمَّ تَذْكُرُواْ نِعْمَةَ رَبِّكُمْ إِذَا اسْتَوَيْتُمْ عَلَيْهِ\n\r\n\n\r\n(மேலும் உங்களுக்காகக் கப்பல்களையும், நீங்கள் சவாரி செய்யும் கால்நடைகளையும் அவன் ஏற்படுத்தியுள்ளான். அவற்றின் முதுகுகளில் நீங்கள் ஏறுவதற்காகவும், அதன் மீது நீங்கள் ஏறியதும் உங்கள் இறைவனின் அருளை நினைவுகூர்வதற்காகவும்) (43:12,13). மேலும் அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَءَايَةٌ لَّهُمْ أَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِى الْفُلْكِ الْمَشْحُونِ - وَخَلَقْنَا لَهُمْ مِّن مِّثْلِهِ مَا يَرْكَبُونَ\n\r\n\n\r\n(மேலும், அவர்களுக்கு ஓர் அத்தாட்சி என்னவென்றால், நாம் அவர்களின் சந்ததியினரை நிரப்பப்பட்ட கப்பலில் சுமந்து சென்றோம். மேலும், அதைப் போன்றே அவர்கள் சவாரி செய்வதற்காக நாம் அவர்களுக்காகப் படைத்துள்ளோம்.) (36:41,42). கதாதா (ரழி) அவர்கள் கூறுகையில், \"இந்த உம்மத்தின் முதல் தலைமுறையினர் அக்கப்பலைப் பார்க்கும் வரை அல்லாஹ் அதனை நிலைக்கச் செய்தான்\" என்றார்கள். எனினும், இது பொதுவாக அனைத்துக் கப்பல்களையும் குறிக்கும் என்ற முதல் கருத்தே மிகவும் பொருத்தமானது. அல்லாஹ் தொடர்ந்து கூறுகிறான்:\n\r\n\n\r\nوَتَعِيَهَآ أُذُنٌ وَعِيَةٌ\n\r\n\n\r\n(மேலும் அதனை நினைவில் கொள்ளும் காதுகள் கிரகித்துக் கொள்வதற்காக.) அதாவது, உள்வாங்கும் திறன் கொண்ட காதுகள் இந்த அருளைப் புரிந்து சிந்திப்பதற்காக. இப்னு அப்பாஸ் (ரழி) அவர்கள், \"இதன் பொருள் நினைவில் வைத்துக் கொள்ளும் மற்றும் கேட்கும் திறன் கொண்ட காது\" என்று கூறினார். கதாதா (ரழி) அவர்கள் கூறுகையில்:\n\r\n\n\r\nأُذُنٌ وَعِيَةٌ\n\r\n\n\r\n(நினைவில் கொள்ளும் காதுகளால்.) \"அல்லாஹ் நுண்ணறிவை வழங்கிய காது; அது அல்லாஹ்வின் வேதத்தைக் கேட்டுப் பயனடைகிறது\" என்று விளக்கினார்கள். அத்-தஹ்ஹாக் (ரழி) அவர்கள் கூறுகையில்:\n\r\n\n\r\nوَتَعِيَهَآ أُذُنٌ وَعِيَةٌ\n\r\n\n\r\n(மேலும் அதை நினைவில் கொள்ளும் காதுகள் நினைவில் வைத்துக் கொள்வதற்காக.) (69:12) \"அதனைக் கேட்டு நினைவில் கொள்ளும் காது, அதாவது ஆரோக்கியமான செவித்திறனும் சரியான புத்தியும் கொண்ட நபர்\" என்று விளக்கினார்கள். இது இறைவசனங்களைப் புரிந்து உள்வாங்கிக் கொள்ளும் அனைவரையும் குறிக்கும் பொதுவான கருத்தாகும்."},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=18\" class=\"link\">69:18</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:18 ஐ பார்க்கவும்"},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=18\" class=\"link\">69:18</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:18 ஐ பார்க்கவும்"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=18\" class=\"link\">69:18</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:18 ஐ பார்க்கவும்"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=18\" class=\"link\">69:18</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:18 ஐ பார்க்கவும்"},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=18\" class=\"link\">69:18</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:18 ஐ பார்க்கவும்"},"18":{"html":"<strong>மறுமை நாளின் பயங்கரங்கள் பற்றிய ஒரு குறிப்பு</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">نُفِخَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الصُّورِ</span> <span class=\"quran-arabic-font text-success\">نَفْخَةٌ</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةٌ</span><br />\r\n<br />\r\n(சூர் (எக்காளம்) ஒரு முறை ஊதப்படும்போது,)<br />\r\n<br />\r\nமறுமை நாளில் நிகழவிருக்கும் பயங்கரங்களைப் பற்றி அல்லாஹ் அறிவிக்கிறான். இந்நிகழ்வுகளில் முதலாவது, (ஸூரில்) அச்சத்தை ஏற்படுத்தும் ஊதுதலாகும். அதனைத் தொடர்ந்து அழிவுக்குரிய ஊதுதல் நிகழும்; அப்போது அல்லாஹ் நாடியவர்களைத் தவிர வானங்களிலும் பூமியிலும் உள்ள அனைவரும் மூர்ச்சையாகி விழுவார்கள். அதன் பிறகு, அகிலங்களின் இறைவனுக்கு முன்னால் நிற்பதற்கான ஊதுதல் நிகழும்; அதுவே உயிர்த்தெழுதலும் ஒன்றுதிரட்டப்படுதலும் ஆகும். இந்த வசனத்தில் குறிப்பிடப்படுவது அந்த ஊதுதலையே ஆகும். இது ஒரே ஒரு முறை ஊதப்படும் என்பது இங்கே வலியுறுத்தப்படுகிறது. ஏனெனில், அல்லாஹ்வின் கட்டளையை எவராலும் எதிர்க்கவோ தடுக்கவோ முடியாது; அதற்குத் திரும்பத் திரும்பக் கூறுவதோ அல்லது வலியுறுத்துவதோ அவசியமில்லை. எனவேதான் அல்லாஹ் பின்வருமாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَحُمِلَتِ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">وَالْجِبَالُ</span> <span class=\"quran-arabic-font text-success\">فَدُكَّتَا</span> <span class=\"quran-arabic-font text-success\">دَكَّةً</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةً</span><br />\r\n<br />\r\n(பூமியும் மலைகளும் அவற்றின் இடங்களிலிருந்து அகற்றப்பட்டு, அவை இரண்டும் ஒரேயடியாகத் தூள் தூளாக்கப்படும்.) அதாவது, அவை பூமியின் மேற்பரப்பிற்கு இணையாகச் சமமாக்கப்படும். மேலும், பூமி இப்போதுள்ள நிலையைத் தவிர வேறொரு நிலைக்கு மாற்றப்படும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَيَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">وَقَعَتِ</span> <span class=\"quran-arabic-font text-success\">الْوَاقِعَةُ</span><br />\r\n<br />\r\n(அந்நாளில் அந்தப் பெரும் சம்பவம் நிகழும்.) அதாவது, மறுமை நாள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَانشَقَّتِ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءُ</span> <span class=\"quran-arabic-font text-success\">فَهِىَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">وَاهِيَةٌ</span><br />\r\n<br />\r\n(மேலும் வானம் பிளந்துவிடும்; அந்நாளில் அது பலவீனமடைந்து கிழிந்து தொங்கும்.) இப்னு ஜுரைஜ் அவர்கள் கூறினார்கள்: \"இது அல்லாஹ்வின் இந்த வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَفُتِحَتِ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءُ</span> <span class=\"quran-arabic-font text-success\">فَكَانَتْ</span> <span class=\"quran-arabic-font text-success\">أَبْوَابًا</span><br />\r\n<br />\r\n(வானம் திறக்கப்பட்டு, அது பல வாசல்களாக மாறிவிடும்.) (<a href=\"qurandisp.php?sura=78&ayah=19\" class=\"link\">78:19</a>).\" இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அது (வானம்) பிளந்துவிடும், அர்ஷ் (இறைசிம்மாசனம்) அதற்கு அருகில் இருக்கும்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالْمَلَكُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَرْجَآئِهَآ</span><br />\r\n<br />\r\n(வானவர்கள் அதன் ஓரங்களில் இருப்பார்கள்.) இங்கு 'மலக்' என்ற சொல் ஒட்டுமொத்த வானவர் இனத்தைக் குறிக்கிறது. அதாவது, வானவர்கள் அனைவரும் ஒன்றுதிரண்டு வானத்தின் ஓரங்களில் நிற்பார்கள். அர்-ரபீஃ பின் அனஸ் அவர்கள் அல்லாஹ்வின் இந்த வசனத்தைப் பற்றிக் கூறுகையில்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالْمَلَكُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَرْجَآئِهَآ</span><br />\r\n<br />\r\n(வானவர்கள் அதன் ஓரங்களில் இருப்பார்கள்.) \"அதாவது, வானங்கள் தூள் தூளாக்கப்பட்டுச் சிதறிக் கிடக்கும் பகுதிகளின் மீது அவர்கள் நின்று கொண்டு, பூமியில் உள்ள மக்களைப் பார்த்துக் கொண்டிருப்பார்கள்\" என்று விளக்கமளித்தார்கள்.<br />\r\nமேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَحْمِلُ</span> <span class=\"quran-arabic-font text-success\">عَرْشَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">فَوْقَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">ثَمَانِيَةٌ</span><br />\r\n<br />\r\n(அந்நாளில் உமது இறைவனின் அர்ஷை (சிம்மாசனத்தை) தங்களுக்கு மேலே எட்டு (வானவர்கள்) சுமந்து கொண்டிருப்பார்கள்.)<br />\r\n<br />\r\n<strong>ஆதமின் மக்கள் அல்லாஹ்வுக்கு முன்னால் நிறுத்தப்படுதல்</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் இந்த வசனத்தைப் பற்றி:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">تُعْرَضُونَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَخْفَى</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ</span> <span class=\"quran-arabic-font text-success\">خَافِيَةٌ</span><br />\r\n<br />\r\n(அந்நாளில் நீங்கள் (விசாரணைக்காக) கொண்டு வரப்படுவீர்கள்; உங்களில் எந்த இரகசியமும் மறைந்திருக்காது.) அதாவது, 'மறைவானவற்றையும் அந்தரங்க ஆலோசனைகளையும் நன்கு அறிந்தவனிடம் நீங்கள் அனைவரும் கொண்டு வரப்படுவீர்கள். உங்களுடைய எந்தவொரு காரியமும் அவனுக்கு மறைவானதல்ல. வெளிப்படையானவை, இரகசியமானவை மற்றும் ஒளித்து வைக்கப்பட்டவை என அனைத்தையும் அவன் அறிந்தவன்.' இதனால்தான் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَخْفَى</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ</span> <span class=\"quran-arabic-font text-success\">خَافِيَةٌ</span><br />\r\n<br />\r\n(உங்களில் எந்த இரகசியமும் மறைந்திருக்காது.) இமாம் அஹ்மத் அவர்கள் அபூ மூஸா (ரழி) அவர்கள் வாயிலாகப் பதிவு செய்துள்ளார்கள்; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يُعْرَضُ</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">ثَلَاثَ</span> <span class=\"quran-arabic-font text-success\">عَرْضَاتٍ،</span> <span class=\"quran-arabic-font text-success\">فَأَمَّا</span> <span class=\"quran-arabic-font text-success\">عَرْضَتَانِ</span> <span class=\"quran-arabic-font text-success\">فَجِدَالٌ</span> <span class=\"quran-arabic-font text-success\">وَمَعَاذِيرُ،</span> <span class=\"quran-arabic-font text-success\">وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">الثَّالِثَةُ</span> <span class=\"quran-arabic-font text-success\">فَعِنْدَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">تَطِيرُ</span> <span class=\"quran-arabic-font text-success\">الصُّحُفُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَيْدِي</span> <span class=\"quran-arabic-font text-success\">فَآخِذٌ</span> <span class=\"quran-arabic-font text-success\">بِيَمِينِهِ</span> <span class=\"quran-arabic-font text-success\">وَآخِذٌ</span> <span class=\"quran-arabic-font text-success\">بِشِمَالِهِ</span>»<br />\r\n<br />\r\n(மறுமை நாளில் மக்கள் மூன்று முறை விசாரணைக்காக நிறுத்தப்படுவார்கள். முதல் இரண்டு முறையும் தர்க்கம் புரிவதும் சாக்குப்போக்குகள் சொல்வதுமாக அமையும். மூன்றாவது முறையின் போது, (செயல் குறிப்புகள் அடங்கிய) ஏடுகள் கைகளில் பறந்து வரும். அவர்களில் சிலர் தமது ஏடுகளை வலது கையிலும், சிலர் இடது கையிலும் பெற்றுக் கொள்வார்கள்.) இப்னு மாஜா மற்றும் அத்-திர்மிதீ ஆகியோரும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர்.<br />\r\n<br />","text":"மறுமை நாளின் பயங்கரங்கள் பற்றிய ஒரு குறிப்பு\n\r\n\n\r\nفَإِذَا نُفِخَ فِي الصُّورِ نَفْخَةٌ وَاحِدَةٌ\n\r\n\n\r\n(சூர் (எக்காளம்) ஒரு முறை ஊதப்படும்போது,)\n\r\n\n\r\nமறுமை நாளில் நிகழவிருக்கும் பயங்கரங்களைப் பற்றி அல்லாஹ் அறிவிக்கிறான். இந்நிகழ்வுகளில் முதலாவது, (ஸூரில்) அச்சத்தை ஏற்படுத்தும் ஊதுதலாகும். அதனைத் தொடர்ந்து அழிவுக்குரிய ஊதுதல் நிகழும்; அப்போது அல்லாஹ் நாடியவர்களைத் தவிர வானங்களிலும் பூமியிலும் உள்ள அனைவரும் மூர்ச்சையாகி விழுவார்கள். அதன் பிறகு, அகிலங்களின் இறைவனுக்கு முன்னால் நிற்பதற்கான ஊதுதல் நிகழும்; அதுவே உயிர்த்தெழுதலும் ஒன்றுதிரட்டப்படுதலும் ஆகும். இந்த வசனத்தில் குறிப்பிடப்படுவது அந்த ஊதுதலையே ஆகும். இது ஒரே ஒரு முறை ஊதப்படும் என்பது இங்கே வலியுறுத்தப்படுகிறது. ஏனெனில், அல்லாஹ்வின் கட்டளையை எவராலும் எதிர்க்கவோ தடுக்கவோ முடியாது; அதற்குத் திரும்பத் திரும்பக் கூறுவதோ அல்லது வலியுறுத்துவதோ அவசியமில்லை. எனவேதான் அல்லாஹ் பின்வருமாறு கூறுகிறான்:\n\r\n\n\r\nوَحُمِلَتِ الْأَرْضُ وَالْجِبَالُ فَدُكَّتَا دَكَّةً وَاحِدَةً\n\r\n\n\r\n(பூமியும் மலைகளும் அவற்றின் இடங்களிலிருந்து அகற்றப்பட்டு, அவை இரண்டும் ஒரேயடியாகத் தூள் தூளாக்கப்படும்.) அதாவது, அவை பூமியின் மேற்பரப்பிற்கு இணையாகச் சமமாக்கப்படும். மேலும், பூமி இப்போதுள்ள நிலையைத் தவிர வேறொரு நிலைக்கு மாற்றப்படும்.\n\r\n\n\r\nفَيَوْمَئِذٍ وَقَعَتِ الْوَاقِعَةُ\n\r\n\n\r\n(அந்நாளில் அந்தப் பெரும் சம்பவம் நிகழும்.) அதாவது, மறுமை நாள்.\n\r\n\n\r\nوَانشَقَّتِ السَّمَآءُ فَهِىَ يَوْمَئِذٍ وَاهِيَةٌ\n\r\n\n\r\n(மேலும் வானம் பிளந்துவிடும்; அந்நாளில் அது பலவீனமடைந்து கிழிந்து தொங்கும்.) இப்னு ஜுரைஜ் அவர்கள் கூறினார்கள்: \"இது அல்லாஹ்வின் இந்த வசனத்தைப் போன்றது:\n\r\n\n\r\nوَفُتِحَتِ السَّمَآءُ فَكَانَتْ أَبْوَابًا\n\r\n\n\r\n(வானம் திறக்கப்பட்டு, அது பல வாசல்களாக மாறிவிடும்.) (78:19).\" இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அது (வானம்) பிளந்துவிடும், அர்ஷ் (இறைசிம்மாசனம்) அதற்கு அருகில் இருக்கும்.\"\n\r\n\n\r\nوَالْمَلَكُ عَلَى أَرْجَآئِهَآ\n\r\n\n\r\n(வானவர்கள் அதன் ஓரங்களில் இருப்பார்கள்.) இங்கு 'மலக்' என்ற சொல் ஒட்டுமொத்த வானவர் இனத்தைக் குறிக்கிறது. அதாவது, வானவர்கள் அனைவரும் ஒன்றுதிரண்டு வானத்தின் ஓரங்களில் நிற்பார்கள். அர்-ரபீஃ பின் அனஸ் அவர்கள் அல்லாஹ்வின் இந்த வசனத்தைப் பற்றிக் கூறுகையில்:\n\r\n\n\r\nوَالْمَلَكُ عَلَى أَرْجَآئِهَآ\n\r\n\n\r\n(வானவர்கள் அதன் ஓரங்களில் இருப்பார்கள்.) \"அதாவது, வானங்கள் தூள் தூளாக்கப்பட்டுச் சிதறிக் கிடக்கும் பகுதிகளின் மீது அவர்கள் நின்று கொண்டு, பூமியில் உள்ள மக்களைப் பார்த்துக் கொண்டிருப்பார்கள்\" என்று விளக்கமளித்தார்கள்.\n\r\nமேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٍ ثَمَانِيَةٌ\n\r\n\n\r\n(அந்நாளில் உமது இறைவனின் அர்ஷை (சிம்மாசனத்தை) தங்களுக்கு மேலே எட்டு (வானவர்கள்) சுமந்து கொண்டிருப்பார்கள்.)\n\r\n\n\r\nஆதமின் மக்கள் அல்லாஹ்வுக்கு முன்னால் நிறுத்தப்படுதல்\n\r\n\n\r\nஅல்லாஹ்வின் இந்த வசனத்தைப் பற்றி:\n\r\n\n\r\nيَوْمَئِذٍ تُعْرَضُونَ لاَ تَخْفَى مِنكُمْ خَافِيَةٌ\n\r\n\n\r\n(அந்நாளில் நீங்கள் (விசாரணைக்காக) கொண்டு வரப்படுவீர்கள்; உங்களில் எந்த இரகசியமும் மறைந்திருக்காது.) அதாவது, 'மறைவானவற்றையும் அந்தரங்க ஆலோசனைகளையும் நன்கு அறிந்தவனிடம் நீங்கள் அனைவரும் கொண்டு வரப்படுவீர்கள். உங்களுடைய எந்தவொரு காரியமும் அவனுக்கு மறைவானதல்ல. வெளிப்படையானவை, இரகசியமானவை மற்றும் ஒளித்து வைக்கப்பட்டவை என அனைத்தையும் அவன் அறிந்தவன்.' இதனால்தான் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nلاَ تَخْفَى مِنكُمْ خَافِيَةٌ\n\r\n\n\r\n(உங்களில் எந்த இரகசியமும் மறைந்திருக்காது.) இமாம் அஹ்மத் அவர்கள் அபூ மூஸா (ரழி) அவர்கள் வாயிலாகப் பதிவு செய்துள்ளார்கள்; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يُعْرَضُ النَّاسُ يَوْمَ الْقِيَامَةِ ثَلَاثَ عَرْضَاتٍ، فَأَمَّا عَرْضَتَانِ فَجِدَالٌ وَمَعَاذِيرُ، وَأَمَّا الثَّالِثَةُ فَعِنْدَ ذَلِكَ تَطِيرُ الصُّحُفُ فِي الْأَيْدِي فَآخِذٌ بِيَمِينِهِ وَآخِذٌ بِشِمَالِهِ»\n\r\n\n\r\n(மறுமை நாளில் மக்கள் மூன்று முறை விசாரணைக்காக நிறுத்தப்படுவார்கள். முதல் இரண்டு முறையும் தர்க்கம் புரிவதும் சாக்குப்போக்குகள் சொல்வதுமாக அமையும். மூன்றாவது முறையின் போது, (செயல் குறிப்புகள் அடங்கிய) ஏடுகள் கைகளில் பறந்து வரும். அவர்களில் சிலர் தமது ஏடுகளை வலது கையிலும், சிலர் இடது கையிலும் பெற்றுக் கொள்வார்கள்.) இப்னு மாஜா மற்றும் அத்-திர்மிதீ ஆகியோரும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர்."},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=24\" class=\"link\">69:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:24 ஐ பார்க்கவும்"},"20":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=24\" class=\"link\">69:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:24 ஐ பார்க்கவும்"},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=24\" class=\"link\">69:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:24 ஐ பார்க்கவும்"},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=24\" class=\"link\">69:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:24 ஐ பார்க்கவும்"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=24\" class=\"link\">69:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:24 ஐ பார்க்கவும்"},"24":{"html":"<strong>தனது பதிவேட்டை வலது கையில் பெறுபவரின் மகிழ்ச்சியும் அவரது நல்நிலையும்</strong><br />\r\n<br />\r\nமறுமை நாளில் தமது செயல் பதிவேட்டை வலது கையில் பெறுவோரின் மகிழ்ச்சியைப் பற்றியும், அது குறித்து அவர்கள் அடையும் திருப்தியைப் பற்றியும் அல்லாஹ் கூறுகிறான். தனது மட்டற்ற மகிழ்ச்சியின் காரணமாக, அவர் சந்திக்கும் ஒவ்வொருவரிடமும் இவ்வாறு கூறுவார்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَآؤُمُ</span> <span class=\"quran-arabic-font text-success\">اقْرَؤُاْ</span> <span class=\"quran-arabic-font text-success\">كِتَابِيَهْ</span><br />\r\n<br />\r\n(இதோ! எனது பதிவேட்டைப் படியுங்கள்!) அதாவது, \"எனது பதிவேட்டைப் பெற்று அதைப் படியுங்கள்\" என்று கூறுவார். அவர் இவ்வாறு கூறுவதற்குக் காரணம், அதில் நற்செயல்களும் தூய்மையான அறப்பணிகளும் மட்டுமே இருப்பதை அவர் அறிந்திருப்பார். அல்லாஹ் யாருடைய தீய செயல்களை நற்செயல்களாக மாற்றினானோ, அவர்களில் இவரும் ஒருவராக இருப்பார். அப்துர் ரஹ்மான் பின் ஸைத் கூறினார்கள்: \"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَآؤُمُ</span> <span class=\"quran-arabic-font text-success\">اقْرَؤُاْ</span> <span class=\"quran-arabic-font text-success\">كِتَابِيَهْ</span><br />\r\n<br />\r\n(இதோ! எனது பதிவேட்டைப் படியுங்கள்!) என்பதன் பொருள் 'இதோ, என் பதிவேட்டைப் படியுங்கள்' என்பதாகும். இதில் உள்ள 'உம்' (Um) என்ற பின்னொட்டு ஒரு இலக்கணச் சேர்ப்பாகும்.\" இது அப்துர் ரஹ்மான் அவர்கள் கூறிய கருத்தாகும். ஆனால், இங்கே 'உம்' என்ற பின்னொட்டு 'நீங்கள் அனைவரும்' என்பதைக் குறிப்பதாகவே வெளிப்படையாகத் தெரிகிறது. இப்னு அபீ ஹாதிம் அவர்கள் அப்துல்லாஹ் பின் அப்துல்லாஹ் பின் ஹன்ழலா (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள் - ஹன்ழலா (ரழி) அவர்கள் வானவர்களால் ஜனாஸா குளிப்பாட்டப்பட்ட சிறப்புக்குரிய நபித்தோழர் ஆவார் - அவர்கள் கூறினார்கள்: \"நிச்சயமாக, மறுமை நாளில் அல்லாஹ் தனது அடியானை நிறுத்தி, அவனது பாவங்களை அவனது செயல் பதிவேட்டின் வெளிப்புறத்தில் தெரியும்படி செய்வான். பிறகு அவனிடம், 'நீ இதைச் செய்தாயா?' என்று கேட்பான். அதற்கு அந்த அடியான், 'ஆம் என் இறைவனே!' என்று பதிலளிப்பான். பிறகு அல்லாஹ் அவனிடம், 'இதற்காக நான் உன்னை இழிவுபடுத்த மாட்டேன்; நிச்சயமாக நான் உன்னை மன்னித்துவிட்டேன்' என்று கூறுவான். அப்போது அந்த நபர் மகிழ்ச்சியில், 'இதோ (நீங்கள் அனைவரும்) என் பதிவேட்டைப் படியுங்கள்!' என்று கூறுவார்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">ظَنَنتُ</span> <span class=\"quran-arabic-font text-success\">أَنِّى</span> <span class=\"quran-arabic-font text-success\">مُلَاقٍ</span> <span class=\"quran-arabic-font text-success\">حِسَابِيَهْ</span><br />\r\n<br />\r\n(நிச்சயமாக, நான் எனது கணக்கைச் சந்திப்பேன் என்று உறுதியாக நம்பியிருந்தேன்!) மறுமை நாளில் அந்த அடியான் இழிவுபடுத்தப்படுவதிலிருந்தும், அம்பலப்படுத்தப்படுவதிலிருந்தும் காப்பாற்றப்படும்போது இவ்வாறு கூறுவார். ஸஹீஹ் நூலில் இப்னு உமர் (ரழி) அவர்களிடம் (அல்லாஹ்வுக்கும் அடியானுக்கும் இடையிலான) இரகசிய உரையாடலைப் பற்றிக் கேட்கப்பட்டது. அதற்கு அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறக் கேட்டதாகப் பதிலளித்தார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يُدْنِي</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">الْعَبْدَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">فَيُقَرِّرُهُ</span> <span class=\"quran-arabic-font text-success\">بِذُنُوبِهِ</span> <span class=\"quran-arabic-font text-success\">كُلِّهَا،</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">رَأَى</span> <span class=\"quran-arabic-font text-success\">أَنَّهُ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">هَلَكَ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">تَعَالى</span>: <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">سَتَرْتُهَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَأَنَا</span> <span class=\"quran-arabic-font text-success\">أَغْفِرُهَا</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُعْطَى</span> <span class=\"quran-arabic-font text-success\">كِتَابَ</span> <span class=\"quran-arabic-font text-success\">حَسَنَاتِهِ</span> <span class=\"quran-arabic-font text-success\">بِيَمِينِهِ</span>. <span class=\"quran-arabic-font text-success\">وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">الْكَافِرُ</span> <span class=\"quran-arabic-font text-success\">وَالْمُنَافِقُ</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">الْأَشْهَادُ</span><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَـؤُلاءِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَذَبُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">أَلاَ</span> <span class=\"quran-arabic-font text-success\">لَعْنَةُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الظَّالِمِينَ</span>»<br />\r\n<br />\r\n(மறுமை நாளில் அல்லாஹ் ஓர் அடியானைத் தனக்கு நெருக்கமாகக் கொண்டுவந்து, அவனது பாவங்கள் அனைத்தையும் அவனிடம் ஒப்புக்கொள்ளச் செய்வான். தான் அழிந்துவிடுவோம் என்று அந்த அடியான் நினைக்கும் வரை இது தொடரும். பிறகு அல்லாஹ் கூறுவான்: \"நிச்சயமாக, இவ்வுலக வாழ்வில் இந்தப் பாவங்களை உனக்காக நான் மறைத்து வைத்திருந்தேன், இன்று உனக்காக அவற்றை மன்னித்துவிட்டேன்.\" பின்னர் அவனது நற்செயல்களின் பதிவேடு அவனது வலது கையில் கொடுக்கப்படும். ஆனால், நிராகரிப்பாளர்கள் மற்றும் நயவஞ்சகர்களைப் பற்றி சாட்சிகள் கூறுவார்கள்: \"இவர்கள்தான் தங்கள் இறைவன் மீது பொய் சொன்னவர்கள்; இத்தகைய அநியாயக்காரர்களின் மீது அல்லாஹ்வின் சாபம் உண்டாகட்டும்.\") அல்லாஹ்வின் கூற்றான,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">ظَنَنتُ</span> <span class=\"quran-arabic-font text-success\">أَنِّى</span> <span class=\"quran-arabic-font text-success\">مُلَاقٍ</span> <span class=\"quran-arabic-font text-success\">حِسَابِيَهْ</span><br />\r\n<br />\r\n(நிச்சயமாக, நான் எனது கணக்கைச் சந்திப்பேன் என்று உறுதியாக நம்பியிருந்தேன்!) என்பதன் பொருள், 'இவ்வுலகில் வாழ்ந்தபோது இந்த நாள் நிச்சயமாக வரும் என்று நான் உறுதியாக நம்பியிருந்தேன்' என்பதாகும். இது அல்லாஹ் பின்வரும் வசனத்தில் கூறுவதைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَظُنُّونَ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُم</span> <span class=\"quran-arabic-font text-success\">مُّلَاقُوا</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span><br />\r\n<br />\r\n(அவர்கள் எத்தகையோரென்றால், தாங்கள் தங்கள் இறைவனைச் சந்திப்போம் என்று உறுதியாக நம்புபவர்கள்.) (<a href=\"qurandisp.php?sura=2&ayah=46\" class=\"link\">2:46</a>). பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">عِيشَةٍ</span> <span class=\"quran-arabic-font text-success\">رَّاضِيَةٍ</span><br />\r\n<br />\r\n(எனவே, அவர் திருப்திகரமான வாழ்க்கையில் இருப்பார்.) (<a href=\"qurandisp.php?sura=69&ayah=21\" class=\"link\">69:21</a>) அதாவது, இன்பமான வாழ்க்கை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">جَنَّةٍ</span> <span class=\"quran-arabic-font text-success\">عَالِيَةٍ</span><br />\r\n<br />\r\n(உயர்ந்த சுவனத்தில்,) அதாவது உயர்ந்த மாளிகைகள், அகன்ற விழிகளையுடைய அழகிய கன்னியர், மனமகிழ்வான தங்குமிடங்கள் மற்றும் நிலையான மகிழ்ச்சியைக் கொண்ட சுவனத்தில் இருப்பார். ஸஹீஹ் நூலில் நபி (ஸல்) அவர்கள் இவ்வாறு கூறியதாக உறுதிப்படுத்தப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ</span> <span class=\"quran-arabic-font text-success\">مِائَةُ</span> <span class=\"quran-arabic-font text-success\">دَرَجَةٍ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">دَرَجَتَيْنِ</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْض</span>»<br />\r\n<br />\r\n(நிச்சயமாக, சுவனத்தில் நூறு அந்தஸ்துகள் உள்ளன; ஒவ்வொரு அந்தஸ்துக்கும் இடைப்பட்ட தூரம் பூமிக்கும் வானத்திற்கும் இடைப்பட்ட தூரத்தைப் போன்றதாகும்.) பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُطُوفُهَا</span> <span class=\"quran-arabic-font text-success\">دَانِيَةٌ</span><br />\r\n<br />\r\n(அதன் பழக்குலைகள் தாழ்வாகவும் (பறிப்பதற்கு) மிக அருகிலும் இருக்கும்.) அல்-பராஃ பின் ஆஸிப் (ரழி) அவர்கள் கூறினார்கள்: \"இதன் பொருள், சுவனவாசிகளில் ஒருவர் தமது படுக்கையில் சாய்ந்திருக்கும் போதே அவற்றைப் பறிக்கும் அளவிற்கு அவை மிக நெருக்கமாக இருக்கும் என்பதாகும்.\" பல அறிஞர்கள் இவ்வாறு கூறியுள்ளனர். பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كُلُواْ</span> <span class=\"quran-arabic-font text-success\">وَاشْرَبُواْ</span> <span class=\"quran-arabic-font text-success\">هَنِيئَاً</span> <span class=\"quran-arabic-font text-success\">بِمَآ</span> <span class=\"quran-arabic-font text-success\">أَسْلَفْتُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْأَيَّامِ</span> <span class=\"quran-arabic-font text-success\">الْخَالِيَةِ</span><br />\r\n<br />\r\n(சென்ற நாட்களில் நீங்கள் முன்கூட்டியே செய்த நற்செயல்களுக்காக, மகிழ்ச்சியுடன் உண்ணுங்கள், பருகுங்கள்!) இது அவர்களுக்கு அளிக்கப்படும் உபசரிப்பாகவும், அருட்கொடையாகவும் கூறப்படும். ஏனெனில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியது ஸஹீஹ் நூலில் உறுதிப்படுத்தப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اعْمَلُوا</span> <span class=\"quran-arabic-font text-success\">وَسَدِّدُوا</span> <span class=\"quran-arabic-font text-success\">وَقَارِبُوا،</span> <span class=\"quran-arabic-font text-success\">وَاعْلَمُوا</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">أَحَدًا</span> <span class=\"quran-arabic-font text-success\">مِنْكُمْ</span> <span class=\"quran-arabic-font text-success\">لَنْ</span> <span class=\"quran-arabic-font text-success\">يُدْخِلَهُ</span> <span class=\"quran-arabic-font text-success\">عَمَلُهُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّة</span>»<br />\r\n<br />\r\n(நற்செயல்கள் புரியுங்கள், நேர்மையைக் கடைப்பிடியுங்கள், (அல்லாஹ்வின் நெருக்கத்தைப் பெற) முயலுங்கள். மேலும் அறிந்து கொள்ளுங்கள், உங்களில் எவரையும் அவரது செயல் மட்டும் சுவனத்தில் நுழைவித்து விடாது.) ஸஹாபாக்கள் (ரழி) அவர்கள் கேட்டார்கள்: \"அல்லாஹ்வின் தூதரே! நீங்களுமா?\" அதற்கு அவர்கள் (ஸல்) பதிலளித்தார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَتَغَمَّدَنِيَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">بِرَحْمَةٍ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">وَفَضْل</span>»<br />\r\n<br />\r\n(நானும் தான்; அல்லாஹ் தனது பேரருளாலும் கிருபையாலும் என்னைச் சூழ்ந்து கொண்டாலன்றி நானும் சுவனம் செல்ல முடியாது.)<br />\r\n<br />\r\n<br />\r\n<br />","text":"தனது பதிவேட்டை வலது கையில் பெறுபவரின் மகிழ்ச்சியும் அவரது நல்நிலையும்\n\r\n\n\r\nமறுமை நாளில் தமது செயல் பதிவேட்டை வலது கையில் பெறுவோரின் மகிழ்ச்சியைப் பற்றியும், அது குறித்து அவர்கள் அடையும் திருப்தியைப் பற்றியும் அல்லாஹ் கூறுகிறான். தனது மட்டற்ற மகிழ்ச்சியின் காரணமாக, அவர் சந்திக்கும் ஒவ்வொருவரிடமும் இவ்வாறு கூறுவார்:\n\r\n\n\r\nهَآؤُمُ اقْرَؤُاْ كِتَابِيَهْ\n\r\n\n\r\n(இதோ! எனது பதிவேட்டைப் படியுங்கள்!) அதாவது, \"எனது பதிவேட்டைப் பெற்று அதைப் படியுங்கள்\" என்று கூறுவார். அவர் இவ்வாறு கூறுவதற்குக் காரணம், அதில் நற்செயல்களும் தூய்மையான அறப்பணிகளும் மட்டுமே இருப்பதை அவர் அறிந்திருப்பார். அல்லாஹ் யாருடைய தீய செயல்களை நற்செயல்களாக மாற்றினானோ, அவர்களில் இவரும் ஒருவராக இருப்பார். அப்துர் ரஹ்மான் பின் ஸைத் கூறினார்கள்: \"\n\r\n\n\r\nهَآؤُمُ اقْرَؤُاْ كِتَابِيَهْ\n\r\n\n\r\n(இதோ! எனது பதிவேட்டைப் படியுங்கள்!) என்பதன் பொருள் 'இதோ, என் பதிவேட்டைப் படியுங்கள்' என்பதாகும். இதில் உள்ள 'உம்' (Um) என்ற பின்னொட்டு ஒரு இலக்கணச் சேர்ப்பாகும்.\" இது அப்துர் ரஹ்மான் அவர்கள் கூறிய கருத்தாகும். ஆனால், இங்கே 'உம்' என்ற பின்னொட்டு 'நீங்கள் அனைவரும்' என்பதைக் குறிப்பதாகவே வெளிப்படையாகத் தெரிகிறது. இப்னு அபீ ஹாதிம் அவர்கள் அப்துல்லாஹ் பின் அப்துல்லாஹ் பின் ஹன்ழலா (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள் - ஹன்ழலா (ரழி) அவர்கள் வானவர்களால் ஜனாஸா குளிப்பாட்டப்பட்ட சிறப்புக்குரிய நபித்தோழர் ஆவார் - அவர்கள் கூறினார்கள்: \"நிச்சயமாக, மறுமை நாளில் அல்லாஹ் தனது அடியானை நிறுத்தி, அவனது பாவங்களை அவனது செயல் பதிவேட்டின் வெளிப்புறத்தில் தெரியும்படி செய்வான். பிறகு அவனிடம், 'நீ இதைச் செய்தாயா?' என்று கேட்பான். அதற்கு அந்த அடியான், 'ஆம் என் இறைவனே!' என்று பதிலளிப்பான். பிறகு அல்லாஹ் அவனிடம், 'இதற்காக நான் உன்னை இழிவுபடுத்த மாட்டேன்; நிச்சயமாக நான் உன்னை மன்னித்துவிட்டேன்' என்று கூறுவான். அப்போது அந்த நபர் மகிழ்ச்சியில், 'இதோ (நீங்கள் அனைவரும்) என் பதிவேட்டைப் படியுங்கள்!' என்று கூறுவார்.\"\n\r\n\n\r\nإِنِّى ظَنَنتُ أَنِّى مُلَاقٍ حِسَابِيَهْ\n\r\n\n\r\n(நிச்சயமாக, நான் எனது கணக்கைச் சந்திப்பேன் என்று உறுதியாக நம்பியிருந்தேன்!) மறுமை நாளில் அந்த அடியான் இழிவுபடுத்தப்படுவதிலிருந்தும், அம்பலப்படுத்தப்படுவதிலிருந்தும் காப்பாற்றப்படும்போது இவ்வாறு கூறுவார். ஸஹீஹ் நூலில் இப்னு உமர் (ரழி) அவர்களிடம் (அல்லாஹ்வுக்கும் அடியானுக்கும் இடையிலான) இரகசிய உரையாடலைப் பற்றிக் கேட்கப்பட்டது. அதற்கு அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறக் கேட்டதாகப் பதிலளித்தார்கள்:\n\r\n\n\r\n«يُدْنِي اللهُ الْعَبْدَ يَوْمَ الْقِيَامَةِ فَيُقَرِّرُهُ بِذُنُوبِهِ كُلِّهَا، حَتَّى إِذَا رَأَى أَنَّهُ قَدْ هَلَكَ قَالَ اللهُ تَعَالى: إِنِّي سَتَرْتُهَا عَلَيْكَ فِي الدُّنْيَا وَأَنَا أَغْفِرُهَا لَكَ الْيَوْمَ، ثُمَّ يُعْطَى كِتَابَ حَسَنَاتِهِ بِيَمِينِهِ. وَأَمَّا الْكَافِرُ وَالْمُنَافِقُ فَيَقُولُ الْأَشْهَادُ\n\r\n\n\r\nهَـؤُلاءِ الَّذِينَ كَذَبُواْ عَلَى رَبِّهِمْ أَلاَ لَعْنَةُ اللَّهِ عَلَى الظَّالِمِينَ»\n\r\n\n\r\n(மறுமை நாளில் அல்லாஹ் ஓர் அடியானைத் தனக்கு நெருக்கமாகக் கொண்டுவந்து, அவனது பாவங்கள் அனைத்தையும் அவனிடம் ஒப்புக்கொள்ளச் செய்வான். தான் அழிந்துவிடுவோம் என்று அந்த அடியான் நினைக்கும் வரை இது தொடரும். பிறகு அல்லாஹ் கூறுவான்: \"நிச்சயமாக, இவ்வுலக வாழ்வில் இந்தப் பாவங்களை உனக்காக நான் மறைத்து வைத்திருந்தேன், இன்று உனக்காக அவற்றை மன்னித்துவிட்டேன்.\" பின்னர் அவனது நற்செயல்களின் பதிவேடு அவனது வலது கையில் கொடுக்கப்படும். ஆனால், நிராகரிப்பாளர்கள் மற்றும் நயவஞ்சகர்களைப் பற்றி சாட்சிகள் கூறுவார்கள்: \"இவர்கள்தான் தங்கள் இறைவன் மீது பொய் சொன்னவர்கள்; இத்தகைய அநியாயக்காரர்களின் மீது அல்லாஹ்வின் சாபம் உண்டாகட்டும்.\") அல்லாஹ்வின் கூற்றான,\n\r\n\n\r\nإِنِّى ظَنَنتُ أَنِّى مُلَاقٍ حِسَابِيَهْ\n\r\n\n\r\n(நிச்சயமாக, நான் எனது கணக்கைச் சந்திப்பேன் என்று உறுதியாக நம்பியிருந்தேன்!) என்பதன் பொருள், 'இவ்வுலகில் வாழ்ந்தபோது இந்த நாள் நிச்சயமாக வரும் என்று நான் உறுதியாக நம்பியிருந்தேன்' என்பதாகும். இது அல்லாஹ் பின்வரும் வசனத்தில் கூறுவதைப் போன்றதாகும்:\n\r\n\n\r\nالَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَاقُوا رَبِّهِمْ\n\r\n\n\r\n(அவர்கள் எத்தகையோரென்றால், தாங்கள் தங்கள் இறைவனைச் சந்திப்போம் என்று உறுதியாக நம்புபவர்கள்.) (2:46). பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَهُوَ فِى عِيشَةٍ رَّاضِيَةٍ\n\r\n\n\r\n(எனவே, அவர் திருப்திகரமான வாழ்க்கையில் இருப்பார்.) (69:21) அதாவது, இன்பமான வாழ்க்கை.\n\r\n\n\r\nفِى جَنَّةٍ عَالِيَةٍ\n\r\n\n\r\n(உயர்ந்த சுவனத்தில்,) அதாவது உயர்ந்த மாளிகைகள், அகன்ற விழிகளையுடைய அழகிய கன்னியர், மனமகிழ்வான தங்குமிடங்கள் மற்றும் நிலையான மகிழ்ச்சியைக் கொண்ட சுவனத்தில் இருப்பார். ஸஹீஹ் நூலில் நபி (ஸல்) அவர்கள் இவ்வாறு கூறியதாக உறுதிப்படுத்தப்பட்டுள்ளது:\n\r\n\n\r\n«إِنَّ الْجَنَّةَ مِائَةُ دَرَجَةٍ مَا بَيْنَ كُلِّ دَرَجَتَيْنِ كَمَا بَيْنَ السَّمَاءِ وَالْأَرْض»\n\r\n\n\r\n(நிச்சயமாக, சுவனத்தில் நூறு அந்தஸ்துகள் உள்ளன; ஒவ்வொரு அந்தஸ்துக்கும் இடைப்பட்ட தூரம் பூமிக்கும் வானத்திற்கும் இடைப்பட்ட தூரத்தைப் போன்றதாகும்.) பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nقُطُوفُهَا دَانِيَةٌ\n\r\n\n\r\n(அதன் பழக்குலைகள் தாழ்வாகவும் (பறிப்பதற்கு) மிக அருகிலும் இருக்கும்.) அல்-பராஃ பின் ஆஸிப் (ரழி) அவர்கள் கூறினார்கள்: \"இதன் பொருள், சுவனவாசிகளில் ஒருவர் தமது படுக்கையில் சாய்ந்திருக்கும் போதே அவற்றைப் பறிக்கும் அளவிற்கு அவை மிக நெருக்கமாக இருக்கும் என்பதாகும்.\" பல அறிஞர்கள் இவ்வாறு கூறியுள்ளனர். பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nكُلُواْ وَاشْرَبُواْ هَنِيئَاً بِمَآ أَسْلَفْتُمْ فِى الْأَيَّامِ الْخَالِيَةِ\n\r\n\n\r\n(சென்ற நாட்களில் நீங்கள் முன்கூட்டியே செய்த நற்செயல்களுக்காக, மகிழ்ச்சியுடன் உண்ணுங்கள், பருகுங்கள்!) இது அவர்களுக்கு அளிக்கப்படும் உபசரிப்பாகவும், அருட்கொடையாகவும் கூறப்படும். ஏனெனில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியது ஸஹீஹ் நூலில் உறுதிப்படுத்தப்பட்டுள்ளது:\n\r\n\n\r\n«اعْمَلُوا وَسَدِّدُوا وَقَارِبُوا، وَاعْلَمُوا أَنَّ أَحَدًا مِنْكُمْ لَنْ يُدْخِلَهُ عَمَلُهُ الْجَنَّة»\n\r\n\n\r\n(நற்செயல்கள் புரியுங்கள், நேர்மையைக் கடைப்பிடியுங்கள், (அல்லாஹ்வின் நெருக்கத்தைப் பெற) முயலுங்கள். மேலும் அறிந்து கொள்ளுங்கள், உங்களில் எவரையும் அவரது செயல் மட்டும் சுவனத்தில் நுழைவித்து விடாது.) ஸஹாபாக்கள் (ரழி) அவர்கள் கேட்டார்கள்: \"அல்லாஹ்வின் தூதரே! நீங்களுமா?\" அதற்கு அவர்கள் (ஸல்) பதிலளித்தார்கள்:\n\r\n\n\r\n«وَلَا أَنَا إِلَّا أَنْ يَتَغَمَّدَنِيَ اللهُ بِرَحْمَةٍ مِنْهُ وَفَضْل»\n\r\n\n\r\n(நானும் தான்; அல்லாஹ் தனது பேரருளாலும் கிருபையாலும் என்னைச் சூழ்ந்து கொண்டாலன்றி நானும் சுவனம் செல்ல முடியாது.)"},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=37\" class=\"link\">69:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:37 ஐ பார்க்கவும்"},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=37\" class=\"link\">69:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:37 ஐ பார்க்கவும்"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=37\" class=\"link\">69:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:37 ஐ பார்க்கவும்"},"28":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=37\" class=\"link\">69:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:37 ஐ பார்க்கவும்"},"29":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=37\" class=\"link\">69:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:37 ஐ பார்க்கவும்"},"30":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=37\" class=\"link\">69:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:37 ஐ பார்க்கவும்"},"31":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=37\" class=\"link\">69:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:37 ஐ பார்க்கவும்"},"32":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=37\" class=\"link\">69:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:37 ஐ பார்க்கவும்"},"33":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=37\" class=\"link\">69:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:37 ஐ பார்க்கவும்"},"34":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=37\" class=\"link\">69:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:37 ஐ பார்க்கவும்"},"35":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=37\" class=\"link\">69:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:37 ஐ பார்க்கவும்"},"36":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=37\" class=\"link\">69:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:37 ஐ பார்க்கவும்"},"37":{"html":"<strong>தனது செயலேடு இடது கையில் கொடுக்கப்படுபவரின் அவல நிலை</strong><br />\r\n<br />\r\nஇந்த வசனங்கள், மக்கள் அல்லாஹ்வின் முன்னிலையில் கொண்டு வரப்படும்போது, துர்ப்பாக்கியசாலிகளில் ஒருவருக்கு அவரது செயலேடு (செயல்கள் அடங்கிய புத்தகம்) இடது கையில் கொடுக்கப்படும் நிலையைப் பற்றி விவரிக்கின்றன. அந்த நேரத்தில் அவன் பெரும் கவலையிலும் வருத்தத்திலும் ஆழ்ந்திருப்பான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أُوتِيَ</span> <span class=\"quran-arabic-font text-success\">كِتَابَهُ</span> <span class=\"quran-arabic-font text-success\">بِشِمَالِهِ</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">لَيْتَنِي</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">أُوتَ</span> <span class=\"quran-arabic-font text-success\">كِتَابِيَهْ</span> - <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">أَدْرِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">حِسَابِيَهْ</span> - <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">لَيْتَهَا</span> <span class=\"quran-arabic-font text-success\">كَانَتِ</span> <span class=\"quran-arabic-font text-success\">الْقَاضِيَةَ</span><br />\r\n<br />\r\n((அவன்) கூறுவான்: \"எனது செயலேடு எனக்குக் கொடுக்கப்படாமல் இருந்திருக்கக் கூடாதா! எனது கணக்கு என்னவென்று நான் அறியாமல் இருந்திருக்கக் கூடாதா! அதுவே (மரணமே) எனது முடிவாக இருந்திருக்கக் கூடாதா!...\") அத்-தஹ்ஹாக் கூறினார்கள்: \"அதாவது, மீண்டும் உயிர் பெறாத ஒரு மரணம் (அதுவே நிரந்தர முடிவாக இருக்க வேண்டும் என விரும்புவான்).\" முஹம்மது பின் கஅப், அர்-ரபீ மற்றும் அஸ்-ஸுத்தீ ஆகியோரும் இதையே கூறினார்கள். கத்தாதா கூறினார்கள்: \"உலக வாழ்க்கையில் அவனுக்கு மிகவும் வெறுப்புக்குரிய விஷயமாக மரணம் இருந்த போதிலும், (அங்குள்ள வேதனையைத் தவிர்க்க) அவன் மரணத்தையே விரும்புவான்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَغْنَى</span> <span class=\"quran-arabic-font text-success\">عَنِّي</span> <span class=\"quran-arabic-font text-success\">مَالِيَهْ</span> - <span class=\"quran-arabic-font text-success\">هَلَكَ</span> <span class=\"quran-arabic-font text-success\">عَنِّي</span> <span class=\"quran-arabic-font text-success\">سُلْطَانِيَهْ</span><br />\r\n<br />\r\n(எனது செல்வம் எனக்குப் பயன் அளிக்கவில்லை; எனது அதிகாரம் என்னை விட்டு நீங்கிவிட்டது.) அதாவது, \"எனது செல்வமும் செல்வாக்கும் அல்லாஹ்வின் தண்டனையிலிருந்தும் அவனது வேதனையிலிருந்தும் என்னைக் காப்பாற்றவில்லை. இப்போது நான் தனித்து விடப்பட்டேன், எனக்கு உதவி செய்யவோ அல்லது என்னைக் காப்பாற்றவோ யாருமில்லை.\" இந்த நிலையில் அல்லாஹ் கூறுவான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">خُذُوهُ</span> <span class=\"quran-arabic-font text-success\">فَغُلُّوهُ</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">الْجَحِيمَ</span> <span class=\"quran-arabic-font text-success\">صَلُّوهُ</span><br />\r\n<br />\r\n(அவனைப் பிடித்து அவனுக்கு விலங்கிடுங்கள்; பின்னர் அவனை நரக நெருப்பில் தள்ளுங்கள்.) அதாவது, அல்லாஹ் நரகத்தின் காவலர்களுக்கு உத்தரவிடுவான்: அவனை ஒன்று கூடும் இடத்திலிருந்து வலுக்கட்டாயமாக அகற்றி, அவனது கழுத்தில் இரும்பு விலங்குகளை மாட்டி, நரகத்திற்கு இழுத்துச் சென்று அதில் எறியுங்கள் - அதாவது அவனை அதில் மூழ்கடியுங்கள். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">سِلْسِلَةٍ</span> <span class=\"quran-arabic-font text-success\">ذَرْعُهَا</span> <span class=\"quran-arabic-font text-success\">سَبْعُونَ</span> <span class=\"quran-arabic-font text-success\">ذِرَاعاً</span> <span class=\"quran-arabic-font text-success\">فَاسْلُكُوهُ</span><br />\r\n<br />\r\n(பின்னர் எழுபது முழம் நீளமுள்ள ஒரு சங்கிலியால் அவனை அதில் கோர்த்துவிடுங்கள்!) கஅப் அல்-அஹ்பார் (ரழி) கூறினார்கள்: \"அந்தச் சங்கிலியின் ஒவ்வொரு வளையமும் உலகில் உள்ள மொத்த இரும்பின் அளவிற்குச் சமமாக இருக்கும்.\" இப்னு அப்பாஸ் (ரழி) மற்றும் இப்னு ஜுரைஜ் (ரழி) ஆகிய இருவரும், \"ஒவ்வொரு முழமும் ஒரு வானவரின் முன்கையின் நீளத்தைக் குறிக்கும்\" என்று கூறியதாக அல்-அவ்ஃபீ அறிவிக்கிறார். இப்னு ஜுரைஜ் (ரழி) அவர்கள் இப்னு அப்பாஸ் (ரழி) கூறியதாக அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاسْلُكُوهُ</span><br />\r\n<br />\r\n(பின்னர் அவனை அதில் கோர்த்துவிடுங்கள்) \"அது அவனது பின்புறம் வழியாக நுழைக்கப்பட்டு வாய் வழியாக வெளியே எடுக்கப்படும். வறுத்தெடுக்கப்படும் குச்சியில் வெட்டுக்கிளிகள் கோர்க்கப்படுவது போல, அவர்கள் இந்தச் சங்கிலியில் கோர்க்கப்படுவார்கள்.\" இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அல்-அவ்ஃபீ அறிவிக்கிறார்: \"அவனால் தனது இரு கால்களால் நிற்க முடியாத அளவுக்கு, அது அவனது பின்புறத்திலிருந்து செலுத்தப்பட்டு மூக்குத் துவாரங்கள் வழியாக வெளியே கொண்டு வரப்படும்.\" இமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்களிடமிருந்து பதிவு செய்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">رَصَاصَةً</span> <span class=\"quran-arabic-font text-success\">مِثْلَ</span> <span class=\"quran-arabic-font text-success\">هذِهِ</span> <span class=\"quran-arabic-font text-success\">وأشار</span> <span class=\"quran-arabic-font text-success\">إلى</span> <span class=\"quran-arabic-font text-success\">جُمْجُمَةٍ</span> <span class=\"quran-arabic-font text-success\">أُرْسِلَتْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ،</span> <span class=\"quran-arabic-font text-success\">وَهِيَ</span> <span class=\"quran-arabic-font text-success\">مَسِيرَةُ</span> <span class=\"quran-arabic-font text-success\">خَمْسِمِائَةِ</span> <span class=\"quran-arabic-font text-success\">سَنَةٍ،</span> <span class=\"quran-arabic-font text-success\">لَبَلَغَتِ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">اللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">أَنَّهَا</span> <span class=\"quran-arabic-font text-success\">أُرْسِلَتْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">رَأْسِ</span> <span class=\"quran-arabic-font text-success\">السِّلْسِلَةِ</span> <span class=\"quran-arabic-font text-success\">لَسَارَتْ</span> <span class=\"quran-arabic-font text-success\">أَرْبَعِينَ</span> <span class=\"quran-arabic-font text-success\">خَرِيفًا</span> <span class=\"quran-arabic-font text-success\">اللَّيْلَ</span> <span class=\"quran-arabic-font text-success\">وَالنَّهَارَ</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تَبْلُغَ</span> <span class=\"quran-arabic-font text-success\">قَعْرَهَا</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أَصْلَهَا</span>»<br />\r\n<br />\r\n(ஒரு மண்டை ஓட்டைப் போன்ற - அதையே நபி (ஸல்) அவர்கள் சுட்டிக்காட்டினார்கள் - ஓர் ஈயக் குண்டு வானத்திலிருந்து பூமிக்கு வீசப்பட்டால், ஐந்நூறு ஆண்டு கால பயணத் தூரம் கொண்ட அந்தப் பாதையை அது இரவுக்கு முன்பே வந்தடைந்துவிடும். ஆனால், நரகச் சங்கிலியின் முனையிலிருந்து அது வீசப்பட்டால், நரகத்தின் ஆழமான தரைப்பகுதியை அடைவதற்கு முன்னால் நாற்பது வருடங்கள் இரவும் பகலும் அது பயணிக்க வேண்டியிருக்கும்.) அத்திர்மிதியும் இந்த ஹதீஸைப் பதிவு செய்துள்ளார்; மேலும் இது \"ஹஸன்\" தரத்திலானது என்றும் அவர் கூறியுள்ளார். அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمِ</span> - <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَحُضُّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">طَعَامِ</span> <span class=\"quran-arabic-font text-success\">الْمِسْكِينِ</span><br />\r\n<br />\r\n(நிச்சயமாக அவன் மகத்தான அல்லாஹ்வை ஈமான் கொள்ளவில்லை; மேலும் அவன் ஏழைகளுக்கு உணவளிப்பதைத் தூண்டவும் இல்லை.) அதாவது, அல்லாஹ்வுக்குக் கீழ்ப்படிந்து அவனை வணங்க வேண்டும் என்ற அல்லாஹ்வின் உரிமையை அவன் நிறைவேற்றவில்லை. அல்லாஹ்வின் படைப்புகளுக்கு அவன் உபகாரம் செய்யவில்லை; அவர்களுக்குச் சேர வேண்டிய உரிமைகளையும் வழங்கவில்லை. நிச்சயமாக, அடியார்கள் அல்லாஹ்வை மட்டுமே வணங்க வேண்டும் என்பதும் அவனுக்கு எதனையும் இணையாக்கக் கூடாது என்பதும் அடியார்கள் மீது அல்லாஹ்வுக்குள்ள உரிமையாகும். அடியார்கள் ஒருவருக்கொருவர் நன்முறையில் நடந்து கொள்வதும், அறச்செயல்களிலும் இறையச்சத்திலும் ஒருவருக்கொருவர் உதவுவதும் அவர்கள் ஒருவருக்கொருவர் செய்ய வேண்டிய கடமையாகும். இதன் காரணமாகவே, அல்லாஹ் தொழுகையை நிலைநாட்டவும் ஜகாத்தை வழங்கவும் கட்டளையிட்டுள்ளான். நபி (ஸல்) அவர்கள் மரணத் தறுவாயில் இருந்தபோது கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الصَّلَاةَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">مَلَكَتْ</span> <span class=\"quran-arabic-font text-success\">أَيْمَانُكُم</span>»<br />\r\n<br />\r\n(தொழுகையையும், உங்கள் வலக்கரங்கள் உரிமையாக்கிக் கொண்டவர்களையும் (அடிமைகள்) கவனத்தில் கொள்ளுங்கள்.)<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">هَـهُنَا</span> <span class=\"quran-arabic-font text-success\">حَمِيمٌ</span> - <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">طَعَامٌ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">غِسْلِينٍ</span> - <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَأْكُلُهُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الْخَاطِئُونَ</span><br />\r\n<br />\r\n(எனவே இன்று அவனுக்கு இங்கே எந்த நண்பனும் இல்லை. காயங்களைக் கழுவிய சீழ் கலந்த நீரைத் தவிர வேறு எந்த உணவும் அவனுக்கு இல்லை. பாவம் செய்தவர்களைத் தவிர வேறு யாரும் அதனை உண்ண மாட்டார்கள்.) அதாவது, இன்று அவனை அல்லாஹ்வின் தண்டனையிலிருந்து காப்பாற்ற எவரும் இல்லை; பரிந்துரைக்க நெருங்கிய நண்பரோ அல்லது சிபாரிசு செய்பவரோ இல்லை. காயங்களைக் கழுவிய அசுத்தமான கழிவைத் தவிர அவனுக்கு வேறு உணவே இருக்காது. கத்தாதா கூறினார்கள்: \"இது நரகவாசிகளின் உணவிலேயே மிக மோசமானதாக இருக்கும்.\" அர்-ரபீ மற்றும் அத்-தஹ்ஹாக் ஆகிய இருவரும், \"கிஸ்லீன் என்பது நரகத்தில் உள்ள ஒரு மரம்\" என்று கூறினார்கள். இப்னு அப்பாஸ் (ரழி) கூறியதாக இக்ரிமா வழியாக ஷபீப் பின் பிஷ்ர் அறிவிக்கிறார்: \"கிஸ்லீன் என்பது அவர்களின் சதையிலிருந்து வடியும் இரத்தமும் திரவமும் ஆகும்.\" அலீ பின் அபீ தல்ஹா அவர்கள் இப்னு அப்பாஸ் (ரழி) கூறியதாக அறிவிக்கிறார்கள்: \"கிஸ்லீன் என்பது நரகவாசிகளின் சீழ் ஆகும்.\"<br />\r\n<br />\r\n<br />\r\n<br />","text":"தனது செயலேடு இடது கையில் கொடுக்கப்படுபவரின் அவல நிலை\n\r\n\n\r\nஇந்த வசனங்கள், மக்கள் அல்லாஹ்வின் முன்னிலையில் கொண்டு வரப்படும்போது, துர்ப்பாக்கியசாலிகளில் ஒருவருக்கு அவரது செயலேடு (செயல்கள் அடங்கிய புத்தகம்) இடது கையில் கொடுக்கப்படும் நிலையைப் பற்றி விவரிக்கின்றன. அந்த நேரத்தில் அவன் பெரும் கவலையிலும் வருத்தத்திலும் ஆழ்ந்திருப்பான்.\n\r\n\n\r\nوَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِشِمَالِهِ فَيَقُولُ يَا لَيْتَنِي لَمْ أُوتَ كِتَابِيَهْ - وَلَمْ أَدْرِ مَا حِسَابِيَهْ - يَا لَيْتَهَا كَانَتِ الْقَاضِيَةَ\n\r\n\n\r\n((அவன்) கூறுவான்: \"எனது செயலேடு எனக்குக் கொடுக்கப்படாமல் இருந்திருக்கக் கூடாதா! எனது கணக்கு என்னவென்று நான் அறியாமல் இருந்திருக்கக் கூடாதா! அதுவே (மரணமே) எனது முடிவாக இருந்திருக்கக் கூடாதா!...\") அத்-தஹ்ஹாக் கூறினார்கள்: \"அதாவது, மீண்டும் உயிர் பெறாத ஒரு மரணம் (அதுவே நிரந்தர முடிவாக இருக்க வேண்டும் என விரும்புவான்).\" முஹம்மது பின் கஅப், அர்-ரபீ மற்றும் அஸ்-ஸுத்தீ ஆகியோரும் இதையே கூறினார்கள். கத்தாதா கூறினார்கள்: \"உலக வாழ்க்கையில் அவனுக்கு மிகவும் வெறுப்புக்குரிய விஷயமாக மரணம் இருந்த போதிலும், (அங்குள்ள வேதனையைத் தவிர்க்க) அவன் மரணத்தையே விரும்புவான்.\"\n\r\n\n\r\nمَآ أَغْنَى عَنِّي مَالِيَهْ - هَلَكَ عَنِّي سُلْطَانِيَهْ\n\r\n\n\r\n(எனது செல்வம் எனக்குப் பயன் அளிக்கவில்லை; எனது அதிகாரம் என்னை விட்டு நீங்கிவிட்டது.) அதாவது, \"எனது செல்வமும் செல்வாக்கும் அல்லாஹ்வின் தண்டனையிலிருந்தும் அவனது வேதனையிலிருந்தும் என்னைக் காப்பாற்றவில்லை. இப்போது நான் தனித்து விடப்பட்டேன், எனக்கு உதவி செய்யவோ அல்லது என்னைக் காப்பாற்றவோ யாருமில்லை.\" இந்த நிலையில் அல்லாஹ் கூறுவான்:\n\r\n\n\r\nخُذُوهُ فَغُلُّوهُ - ثُمَّ الْجَحِيمَ صَلُّوهُ\n\r\n\n\r\n(அவனைப் பிடித்து அவனுக்கு விலங்கிடுங்கள்; பின்னர் அவனை நரக நெருப்பில் தள்ளுங்கள்.) அதாவது, அல்லாஹ் நரகத்தின் காவலர்களுக்கு உத்தரவிடுவான்: அவனை ஒன்று கூடும் இடத்திலிருந்து வலுக்கட்டாயமாக அகற்றி, அவனது கழுத்தில் இரும்பு விலங்குகளை மாட்டி, நரகத்திற்கு இழுத்துச் சென்று அதில் எறியுங்கள் - அதாவது அவனை அதில் மூழ்கடியுங்கள். அல்லாஹ் கூறினான்:\n\r\n\n\r\nثُمَّ فِي سِلْسِلَةٍ ذَرْعُهَا سَبْعُونَ ذِرَاعاً فَاسْلُكُوهُ\n\r\n\n\r\n(பின்னர் எழுபது முழம் நீளமுள்ள ஒரு சங்கிலியால் அவனை அதில் கோர்த்துவிடுங்கள்!) கஅப் அல்-அஹ்பார் (ரழி) கூறினார்கள்: \"அந்தச் சங்கிலியின் ஒவ்வொரு வளையமும் உலகில் உள்ள மொத்த இரும்பின் அளவிற்குச் சமமாக இருக்கும்.\" இப்னு அப்பாஸ் (ரழி) மற்றும் இப்னு ஜுரைஜ் (ரழி) ஆகிய இருவரும், \"ஒவ்வொரு முழமும் ஒரு வானவரின் முன்கையின் நீளத்தைக் குறிக்கும்\" என்று கூறியதாக அல்-அவ்ஃபீ அறிவிக்கிறார். இப்னு ஜுரைஜ் (ரழி) அவர்கள் இப்னு அப்பாஸ் (ரழி) கூறியதாக அறிவிக்கிறார்கள்:\n\r\n\n\r\nفَاسْلُكُوهُ\n\r\n\n\r\n(பின்னர் அவனை அதில் கோர்த்துவிடுங்கள்) \"அது அவனது பின்புறம் வழியாக நுழைக்கப்பட்டு வாய் வழியாக வெளியே எடுக்கப்படும். வறுத்தெடுக்கப்படும் குச்சியில் வெட்டுக்கிளிகள் கோர்க்கப்படுவது போல, அவர்கள் இந்தச் சங்கிலியில் கோர்க்கப்படுவார்கள்.\" இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அல்-அவ்ஃபீ அறிவிக்கிறார்: \"அவனால் தனது இரு கால்களால் நிற்க முடியாத அளவுக்கு, அது அவனது பின்புறத்திலிருந்து செலுத்தப்பட்டு மூக்குத் துவாரங்கள் வழியாக வெளியே கொண்டு வரப்படும்.\" இமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்களிடமிருந்து பதிவு செய்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَوْ أَنَّ رَصَاصَةً مِثْلَ هذِهِ وأشار إلى جُمْجُمَةٍ أُرْسِلَتْ مِنَ السَّمَاءِ إِلَى الْأَرْضِ، وَهِيَ مَسِيرَةُ خَمْسِمِائَةِ سَنَةٍ، لَبَلَغَتِ الْأَرْضَ قَبْلَ اللَّيْلِ وَلَوْ أَنَّهَا أُرْسِلَتْ مِنْ رَأْسِ السِّلْسِلَةِ لَسَارَتْ أَرْبَعِينَ خَرِيفًا اللَّيْلَ وَالنَّهَارَ قَبْلَ أَنْ تَبْلُغَ قَعْرَهَا أَوْ أَصْلَهَا»\n\r\n\n\r\n(ஒரு மண்டை ஓட்டைப் போன்ற - அதையே நபி (ஸல்) அவர்கள் சுட்டிக்காட்டினார்கள் - ஓர் ஈயக் குண்டு வானத்திலிருந்து பூமிக்கு வீசப்பட்டால், ஐந்நூறு ஆண்டு கால பயணத் தூரம் கொண்ட அந்தப் பாதையை அது இரவுக்கு முன்பே வந்தடைந்துவிடும். ஆனால், நரகச் சங்கிலியின் முனையிலிருந்து அது வீசப்பட்டால், நரகத்தின் ஆழமான தரைப்பகுதியை அடைவதற்கு முன்னால் நாற்பது வருடங்கள் இரவும் பகலும் அது பயணிக்க வேண்டியிருக்கும்.) அத்திர்மிதியும் இந்த ஹதீஸைப் பதிவு செய்துள்ளார்; மேலும் இது \"ஹஸன்\" தரத்திலானது என்றும் அவர் கூறியுள்ளார். அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nإِنَّهُ كَانَ لاَ يُؤْمِنُ بِاللَّهِ الْعَظِيمِ - وَلاَ يَحُضُّ عَلَى طَعَامِ الْمِسْكِينِ\n\r\n\n\r\n(நிச்சயமாக அவன் மகத்தான அல்லாஹ்வை ஈமான் கொள்ளவில்லை; மேலும் அவன் ஏழைகளுக்கு உணவளிப்பதைத் தூண்டவும் இல்லை.) அதாவது, அல்லாஹ்வுக்குக் கீழ்ப்படிந்து அவனை வணங்க வேண்டும் என்ற அல்லாஹ்வின் உரிமையை அவன் நிறைவேற்றவில்லை. அல்லாஹ்வின் படைப்புகளுக்கு அவன் உபகாரம் செய்யவில்லை; அவர்களுக்குச் சேர வேண்டிய உரிமைகளையும் வழங்கவில்லை. நிச்சயமாக, அடியார்கள் அல்லாஹ்வை மட்டுமே வணங்க வேண்டும் என்பதும் அவனுக்கு எதனையும் இணையாக்கக் கூடாது என்பதும் அடியார்கள் மீது அல்லாஹ்வுக்குள்ள உரிமையாகும். அடியார்கள் ஒருவருக்கொருவர் நன்முறையில் நடந்து கொள்வதும், அறச்செயல்களிலும் இறையச்சத்திலும் ஒருவருக்கொருவர் உதவுவதும் அவர்கள் ஒருவருக்கொருவர் செய்ய வேண்டிய கடமையாகும். இதன் காரணமாகவே, அல்லாஹ் தொழுகையை நிலைநாட்டவும் ஜகாத்தை வழங்கவும் கட்டளையிட்டுள்ளான். நபி (ஸல்) அவர்கள் மரணத் தறுவாயில் இருந்தபோது கூறினார்கள்:\n\r\n\n\r\n«الصَّلَاةَ وَمَا مَلَكَتْ أَيْمَانُكُم»\n\r\n\n\r\n(தொழுகையையும், உங்கள் வலக்கரங்கள் உரிமையாக்கிக் கொண்டவர்களையும் (அடிமைகள்) கவனத்தில் கொள்ளுங்கள்.)\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَلَيْسَ لَهُ الْيَوْمَ هَـهُنَا حَمِيمٌ - وَلاَ طَعَامٌ إِلاَّ مِنْ غِسْلِينٍ - لاَّ يَأْكُلُهُ إِلاَّ الْخَاطِئُونَ\n\r\n\n\r\n(எனவே இன்று அவனுக்கு இங்கே எந்த நண்பனும் இல்லை. காயங்களைக் கழுவிய சீழ் கலந்த நீரைத் தவிர வேறு எந்த உணவும் அவனுக்கு இல்லை. பாவம் செய்தவர்களைத் தவிர வேறு யாரும் அதனை உண்ண மாட்டார்கள்.) அதாவது, இன்று அவனை அல்லாஹ்வின் தண்டனையிலிருந்து காப்பாற்ற எவரும் இல்லை; பரிந்துரைக்க நெருங்கிய நண்பரோ அல்லது சிபாரிசு செய்பவரோ இல்லை. காயங்களைக் கழுவிய அசுத்தமான கழிவைத் தவிர அவனுக்கு வேறு உணவே இருக்காது. கத்தாதா கூறினார்கள்: \"இது நரகவாசிகளின் உணவிலேயே மிக மோசமானதாக இருக்கும்.\" அர்-ரபீ மற்றும் அத்-தஹ்ஹாக் ஆகிய இருவரும், \"கிஸ்லீன் என்பது நரகத்தில் உள்ள ஒரு மரம்\" என்று கூறினார்கள். இப்னு அப்பாஸ் (ரழி) கூறியதாக இக்ரிமா வழியாக ஷபீப் பின் பிஷ்ர் அறிவிக்கிறார்: \"கிஸ்லீன் என்பது அவர்களின் சதையிலிருந்து வடியும் இரத்தமும் திரவமும் ஆகும்.\" அலீ பின் அபீ தல்ஹா அவர்கள் இப்னு அப்பாஸ் (ரழி) கூறியதாக அறிவிக்கிறார்கள்: \"கிஸ்லீன் என்பது நரகவாசிகளின் சீழ் ஆகும்.\""},"38":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=43\" class=\"link\">69:43</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:43 ஐ பார்க்கவும்"},"39":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=43\" class=\"link\">69:43</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:43 ஐ பார்க்கவும்"},"40":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=43\" class=\"link\">69:43</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:43 ஐ பார்க்கவும்"},"41":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=43\" class=\"link\">69:43</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:43 ஐ பார்க்கவும்"},"42":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=43\" class=\"link\">69:43</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:43 ஐ பார்க்கவும்"},"43":{"html":"<strong>குர்ஆன் அல்லாஹ்வின் பேச்சு</strong><br />\r\n<br />\r\nஅல்லாஹ் தனது படைப்புகளின் மீது சத்தியம் செய்கிறான்; அவற்றுள் அவனது அத்தாட்சிகள் சில அவனது படைப்பினங்கள் வழியாகத் தென்படுகின்றன. இவை அவனது திருப்பெயர்கள் மற்றும் பண்புகளின் பரிபூரணத்துவத்தையும் உணர்த்துகின்றன. பின்னர், அவர்களால் பார்க்க முடியாத மறைவான விஷயங்களின் மீதும் அவன் சத்தியம் செய்கிறான். இந்தக் குர்ஆன் அவனது சொல், அவனது தூண்டுதல் மற்றும் தனது செய்தியை எடுத்துரைப்பதற்காக அவன் தேர்ந்தெடுத்த அவனது அடியாரும் தூதருமானவருக்கு அருளப்பட்ட வஹீ (இறைச்செய்தி) என்பதற்கு இது ஒரு சத்தியமாகும். அந்தத் தூதர் இந்த அமானிதத்தை (நம்பிக்கைப் பொறுப்பை) உண்மையாக நிறைவேற்றினார்கள். எனவே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">أُقْسِمُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تُبْصِرُونَ</span> - <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تُبْصِرُونَ</span> - <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَقَوْلُ</span> <span class=\"quran-arabic-font text-success\">رَسُولٍ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٍ</span><br />\r\n<br />\r\n(நீங்கள் பார்ப்பவற்றின் மீதும், நீங்கள் பார்க்காதவற்றின் மீதும் நான் சத்தியம் செய்கிறேன். நிச்சயமாக இது ஒரு கண்ணியமிக்க தூதரின் சொல்லாகும்.) அதாவது, முஹம்மது (ஸல்) அவர்கள். அல்லாஹ் அவருக்கு இந்த வர்ணனையை வழங்கினான்; இந்த வர்ணனையானது (செய்தியை) எத்தி வைத்தல் என்ற பொருளைத் தாங்கியுள்ளது. ஏனெனில், ஒரு தூதரின் கடமை அனுப்புபவரிடமிருந்து செய்தியை உரிய முறையில் எத்தி வைப்பதே ஆகும். இதனாலேயே, ஸூரா அத்-தக்வீரில் வானவர் தூதருக்கும் அல்லாஹ் இதே வர்ணனையை வழங்கியுள்ளான். அங்கு அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَقَوْلُ</span> <span class=\"quran-arabic-font text-success\">رَسُولٍ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٍ</span> <span class=\"quran-arabic-font text-success\">ذِي</span> <span class=\"quran-arabic-font text-success\">قُوَّةٍ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">ذِي</span> <span class=\"quran-arabic-font text-success\">الْعَرْشِ</span> <span class=\"quran-arabic-font text-success\">مَكِينٍ</span> <span class=\"quran-arabic-font text-success\">مُطَاعٍ</span> <span class=\"quran-arabic-font text-success\">ثَمَّ</span> <span class=\"quran-arabic-font text-success\">أَمِينٍ</span><br />\r\n<br />\r\n(நிச்சயமாக இது (இந்தக் குர்ஆன்) கண்ணியமிக்க ஒரு தூதரால் கொண்டுவரப்பட்ட சொல்லாகும். அர்ஷுடைய அதிபதியான அல்லாஹ்விடம் அவர் மிகுந்த வல்லமையும் உயர்ந்த அந்தஸ்தும் கொண்டவர். அங்கு (வானவர்களால்) பின்பற்றப்படுபவர், மேலும் நம்பிக்கைக்குரியவர்.) (<a href=\"qurandisp.php?sura=81&ayah=19\" class=\"link\">81:19</a>-21) இங்கு இது ஜிப்ரீல் (அலை) அவர்களைக் குறிக்கிறது. பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">صَاحِبُكُم</span> <span class=\"quran-arabic-font text-success\">بِمَجْنُونٍ</span><br />\r\n<br />\r\n(மேலும், உங்கள் தோழர் பைத்தியக்காரர் அல்ல.) (<a href=\"qurandisp.php?sura=81&ayah=22\" class=\"link\">81:22</a>) அதாவது, முஹம்மது (ஸல்) அவர்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">رَءَاهُ</span> <span class=\"quran-arabic-font text-success\">بِالْأُفُقِ</span> <span class=\"quran-arabic-font text-success\">الْمُبِينِ</span><br />\r\n<br />\r\n(நிச்சயமாக அவர் அவரைத் தெளிவான அடிவானத்தில் கண்டார்.) (<a href=\"qurandisp.php?sura=81&ayah=23\" class=\"link\">81:23</a>) அதாவது, முஹம்மது (ஸல்) அவர்கள், ஜிப்ரீல் (அலை) அவர்களை அல்லாஹ் படைத்த அசல் உருவத்தில் கண்டார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْغَيْبِ</span> <span class=\"quran-arabic-font text-success\">بِضَنِينٍ</span><br />\r\n<br />\r\n(மேலும் அவர் மறைவான செய்திகளைத் தெரிவிப்பதில் கஞ்சத்தனம் உடையவர் அல்ல.) (<a href=\"qurandisp.php?sura=81&ayah=24\" class=\"link\">81:24</a>) இதன் பொருள், அவர் சந்தேகத்திற்குரியவர் அல்ல என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">بِقَوْلِ</span> <span class=\"quran-arabic-font text-success\">شَيْطَانٍ</span> <span class=\"quran-arabic-font text-success\">رَّجِيمٍ</span><br />\r\n<br />\r\n(மேலும் இது (குர்ஆன்) விரட்டப்பட்ட ஷைத்தானின் சொல்லும் அல்ல.) (<a href=\"qurandisp.php?sura=81&ayah=25\" class=\"link\">81:25</a>) இதுவும் இங்கு கூறப்பட்டுள்ள விஷயத்தைப் போன்றதேயாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">بِقَوْلِ</span> <span class=\"quran-arabic-font text-success\">شَاعِرٍ</span> <span class=\"quran-arabic-font text-success\">قَلِيلاً</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">تُؤْمِنُونَ</span> - <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">بِقَوْلِ</span> <span class=\"quran-arabic-font text-success\">كَاهِنٍ</span> <span class=\"quran-arabic-font text-success\">قَلِيلاً</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">تَذَكَّرُونَ</span><br />\r\n<br />\r\n(இது ஒரு கவிஞனின் சொல் அல்ல; நீங்கள் மிகக் குறைவாகவே நம்பிக்கை கொள்கிறீர்கள்! இது ஒரு ஜோதிடரின் சொல்லும் அல்ல; நீங்கள் மிகக் குறைவாகவே சிந்தித்துப் பார்க்கிறீர்கள்!) எனவே, அல்லாஹ் ஒரு சந்தர்ப்பத்தில் 'தூதர்' என்ற சொல்லை வானவர் தூதருக்கும் (ஜிப்ரீல் (அலை)), மற்றொரு சந்தர்ப்பத்தில் மனிதத் தூதருக்கும் (முஹம்மது (ஸல்) அவர்கள்) பயன்படுத்துகிறான். ஏனென்றால், அவர்கள் இருவருமே அல்லாஹ்விடமிருந்து தங்களுக்கு ஒப்படைக்கப்பட்ட அவனது வஹீ (இறைச்செய்தி) மற்றும் பேச்சையே எத்தி வைக்கிறார்கள். ஆகவே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تَنزِيلٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّ</span> <span class=\"quran-arabic-font text-success\">الْعَالَمِينَ</span><br />\r\n<br />\r\n(இது அகிலங்களின் இறைவனிடமிருந்து அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும்.)<br />\r\n<br />","text":"குர்ஆன் அல்லாஹ்வின் பேச்சு\n\r\n\n\r\nஅல்லாஹ் தனது படைப்புகளின் மீது சத்தியம் செய்கிறான்; அவற்றுள் அவனது அத்தாட்சிகள் சில அவனது படைப்பினங்கள் வழியாகத் தென்படுகின்றன. இவை அவனது திருப்பெயர்கள் மற்றும் பண்புகளின் பரிபூரணத்துவத்தையும் உணர்த்துகின்றன. பின்னர், அவர்களால் பார்க்க முடியாத மறைவான விஷயங்களின் மீதும் அவன் சத்தியம் செய்கிறான். இந்தக் குர்ஆன் அவனது சொல், அவனது தூண்டுதல் மற்றும் தனது செய்தியை எடுத்துரைப்பதற்காக அவன் தேர்ந்தெடுத்த அவனது அடியாரும் தூதருமானவருக்கு அருளப்பட்ட வஹீ (இறைச்செய்தி) என்பதற்கு இது ஒரு சத்தியமாகும். அந்தத் தூதர் இந்த அமானிதத்தை (நம்பிக்கைப் பொறுப்பை) உண்மையாக நிறைவேற்றினார்கள். எனவே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَلاَ أُقْسِمُ بِمَا تُبْصِرُونَ - وَمَا لاَ تُبْصِرُونَ - إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ\n\r\n\n\r\n(நீங்கள் பார்ப்பவற்றின் மீதும், நீங்கள் பார்க்காதவற்றின் மீதும் நான் சத்தியம் செய்கிறேன். நிச்சயமாக இது ஒரு கண்ணியமிக்க தூதரின் சொல்லாகும்.) அதாவது, முஹம்மது (ஸல்) அவர்கள். அல்லாஹ் அவருக்கு இந்த வர்ணனையை வழங்கினான்; இந்த வர்ணனையானது (செய்தியை) எத்தி வைத்தல் என்ற பொருளைத் தாங்கியுள்ளது. ஏனெனில், ஒரு தூதரின் கடமை அனுப்புபவரிடமிருந்து செய்தியை உரிய முறையில் எத்தி வைப்பதே ஆகும். இதனாலேயே, ஸூரா அத்-தக்வீரில் வானவர் தூதருக்கும் அல்லாஹ் இதே வர்ணனையை வழங்கியுள்ளான். அங்கு அவன் கூறுகிறான்:\n\r\n\n\r\nإِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ ذِي قُوَّةٍ عِندَ ذِي الْعَرْشِ مَكِينٍ مُطَاعٍ ثَمَّ أَمِينٍ\n\r\n\n\r\n(நிச்சயமாக இது (இந்தக் குர்ஆன்) கண்ணியமிக்க ஒரு தூதரால் கொண்டுவரப்பட்ட சொல்லாகும். அர்ஷுடைய அதிபதியான அல்லாஹ்விடம் அவர் மிகுந்த வல்லமையும் உயர்ந்த அந்தஸ்தும் கொண்டவர். அங்கு (வானவர்களால்) பின்பற்றப்படுபவர், மேலும் நம்பிக்கைக்குரியவர்.) (81:19-21) இங்கு இது ஜிப்ரீல் (அலை) அவர்களைக் குறிக்கிறது. பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَمَا صَاحِبُكُم بِمَجْنُونٍ\n\r\n\n\r\n(மேலும், உங்கள் தோழர் பைத்தியக்காரர் அல்ல.) (81:22) அதாவது, முஹம்மது (ஸல்) அவர்கள்.\n\r\n\n\r\nوَلَقَدْ رَءَاهُ بِالْأُفُقِ الْمُبِينِ\n\r\n\n\r\n(நிச்சயமாக அவர் அவரைத் தெளிவான அடிவானத்தில் கண்டார்.) (81:23) அதாவது, முஹம்மது (ஸல்) அவர்கள், ஜிப்ரீல் (அலை) அவர்களை அல்லாஹ் படைத்த அசல் உருவத்தில் கண்டார்கள்.\n\r\n\n\r\nوَمَا هُوَ عَلَى الْغَيْبِ بِضَنِينٍ\n\r\n\n\r\n(மேலும் அவர் மறைவான செய்திகளைத் தெரிவிப்பதில் கஞ்சத்தனம் உடையவர் அல்ல.) (81:24) இதன் பொருள், அவர் சந்தேகத்திற்குரியவர் அல்ல என்பதாகும்.\n\r\n\n\r\nوَمَا هُوَ بِقَوْلِ شَيْطَانٍ رَّجِيمٍ\n\r\n\n\r\n(மேலும் இது (குர்ஆன்) விரட்டப்பட்ட ஷைத்தானின் சொல்லும் அல்ல.) (81:25) இதுவும் இங்கு கூறப்பட்டுள்ள விஷயத்தைப் போன்றதேயாகும்.\n\r\n\n\r\nوَمَا هُوَ بِقَوْلِ شَاعِرٍ قَلِيلاً مَّا تُؤْمِنُونَ - وَلاَ بِقَوْلِ كَاهِنٍ قَلِيلاً مَّا تَذَكَّرُونَ\n\r\n\n\r\n(இது ஒரு கவிஞனின் சொல் அல்ல; நீங்கள் மிகக் குறைவாகவே நம்பிக்கை கொள்கிறீர்கள்! இது ஒரு ஜோதிடரின் சொல்லும் அல்ல; நீங்கள் மிகக் குறைவாகவே சிந்தித்துப் பார்க்கிறீர்கள்!) எனவே, அல்லாஹ் ஒரு சந்தர்ப்பத்தில் 'தூதர்' என்ற சொல்லை வானவர் தூதருக்கும் (ஜிப்ரீல் (அலை)), மற்றொரு சந்தர்ப்பத்தில் மனிதத் தூதருக்கும் (முஹம்மது (ஸல்) அவர்கள்) பயன்படுத்துகிறான். ஏனென்றால், அவர்கள் இருவருமே அல்லாஹ்விடமிருந்து தங்களுக்கு ஒப்படைக்கப்பட்ட அவனது வஹீ (இறைச்செய்தி) மற்றும் பேச்சையே எத்தி வைக்கிறார்கள். ஆகவே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nتَنزِيلٌ مِّن رَّبِّ الْعَالَمِينَ\n\r\n\n\r\n(இது அகிலங்களின் இறைவனிடமிருந்து அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும்.)"},"44":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=52\" class=\"link\">69:52</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:52 ஐ பார்க்கவும்"},"45":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=52\" class=\"link\">69:52</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:52 ஐ பார்க்கவும்"},"46":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=52\" class=\"link\">69:52</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:52 ஐ பார்க்கவும்"},"47":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=52\" class=\"link\">69:52</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:52 ஐ பார்க்கவும்"},"48":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=52\" class=\"link\">69:52</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:52 ஐ பார்க்கவும்"},"49":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=52\" class=\"link\">69:52</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:52 ஐ பார்க்கவும்"},"50":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=52\" class=\"link\">69:52</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:52 ஐ பார்க்கவும்"},"51":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=69&ayah=52\" class=\"link\">69:52</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 69:52 ஐ பார்க்கவும்"},"52":{"html":"<strong>நபி (ஸல்) அவர்கள் அல்லாஹ்வின் மீது எதையேனும் இட்டுக்கட்டியிருந்தால், அல்லாஹ் அவர்களைத் தண்டித்திருப்பான்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">تَقَوَّلَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">بَعْضَ</span> <span class=\"quran-arabic-font text-success\">الأَقَاوِيلِ</span><br />\r\n<br />\r\n(அவர் நம்மீது சில கூற்றுகளை இட்டுக்கட்டியிருந்தால்,) அதாவது, \"நிராகரிப்பாளர்கள் வாதிடுவது போல முஹம்மது (ஸல்) அவர்கள் நம்மீது எதையேனும் இட்டுக்கட்டி, இந்தத் தூதுச்செய்தியில் எதையேனும் சேர்த்தோ அல்லது நீக்கியோ, அல்லது நாமே சொன்னதாகக் கூறித் தமக்காக எதையேனும் கற்பனை செய்து சொல்லியிருந்தால், நாம் நிச்சயமாக அவர்களைத் தண்டிப்பதில் விரைந்திருப்போம். நிச்சயமாக, முஹம்மது (ஸல்) அவர்கள் (நிராகரிப்பாளர்கள் கூறுவது போல்) இவற்றில் எதையும் செய்யவில்லை.\" எனவே அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لأَخَذْنَا</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">بِالْيَمِينِ</span><br />\r\n<br />\r\n(நாம் நிச்சயமாக அவர்களை அவர்களுடைய வலது கையால் பிடித்திருப்போம்,) வலது கையால் பிடிப்பது மிகவும் வலிமையான பிடி என்பதால், \"நாம் அவர்களை வலது கையால் பிடித்திருப்போம்\" என்று இங்கே கூறப்பட்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لَقَطَعْنَا</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">الْوَتِينَ</span><br />\r\n<br />\r\n(பின்னர் நாம் நிச்சயமாக அவர்களிடமிருந்து அல்-வதீனைத் துண்டித்திருப்போம்,) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அது (அல்-வதீன்) இதயத்தின் தமனியைக் குறிக்கும்; மேலும் அது இதயத்துடன் இணைக்கப்பட்டுள்ள ஒரு நரம்பாகும்.\" இக்ரிமா (ரழி), ஸயீத் பின் ஜுபைர் (ரழி), அல்-ஹகம், கத்தாதா (ரழி), அத்-தஹ்ஹாக் (ரழி), முஸ்லிம் அல்-பாத்தின் மற்றும் அபூ ஸக்ர் ஹுமைத் பின் ஸியாத் ஆகியோரும் இவ்வாறே கூறியுள்ளனர். முஹம்மது பின் கஅப் (ரழி) அவர்கள் கூறினார்கள்: \"அது (அல்-வதீன்) இதயம், அதன் இரத்தம் மற்றும் அதனைச் சுற்றியுள்ள பகுதியைக் குறிக்கும்.\" அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">مِنكُم</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">أَحَدٍ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">حَاجِزِينَ</span><br />\r\n<br />\r\n(உங்களில் எவரும் அவரை விட்டும் (நம் தண்டனையைத்) தடுத்திருக்க முடியாது.) இதன் பொருள், \"நாம் அவர்களுக்கு இத்தகைய தண்டனையை அளிக்க விரும்பினால், உங்களில் எவராலும் நமக்கும் அவர்களுக்கும் இடையில் தடையாக வர முடியாது\" என்பதாகும். இதற்கெல்லாம் பின்னால் உள்ள கருத்து என்னவென்றால், அவர்கள் (முஹம்மது (ஸல்) அவர்கள்) உண்மையானவர், நேர்மையானவர் மற்றும் நேர்வழி பெற்றவர் என்பதாகும். ஏனெனில், அவர்கள் எதனைத் தெரிவிக்க வேண்டும் என்பதை அல்லாஹ்வே தீர்மானித்தான்; மேலும் அற்புதமான அற்புதங்கள் மற்றும் தெளிவான அத்தாட்சிகளைக் கொண்டு அல்லாஹ் அவர்களுக்கு உதவி புரிகிறான். பின்னர் அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَتَذْكِرَةٌ</span> <span class=\"quran-arabic-font text-success\">لِّلْمُتَّقِينَ</span><br />\r\n<br />\r\n(நிச்சயமாக, இது (குர்ஆன்) தக்வா (இறையச்சம்) உடையவர்களுக்கு ஒரு நினைவூட்டலாகும்.) அதாவது குர்ஆன். இது அல்லாஹ் பின்வருமாறு கூறுவதைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">هُدًى</span> <span class=\"quran-arabic-font text-success\">وَشِفَآءٌ</span> <span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ءَاذَانِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَقْرٌ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">عَمًى</span><br />\r\n<br />\r\n(கூறுவீராக: \"இது ஈமான் கொண்டவர்களுக்கு ஒரு வழிகாட்டியாகவும், ஒரு நிவாரணமாகவும் இருக்கிறது. நம்பிக்கை கொள்ளாதவர்களைப் பொறுத்தவரை, அவர்களின் காதுகளில் ஒரு செவிட்டுத்தன்மை இருக்கிறது; மேலும் அது (குர்ஆன்) அவர்களுக்குக் குருட்டுத்தன்மையாகும்.\") பின்னர் அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">لَنَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">مِنكُم</span> <span class=\"quran-arabic-font text-success\">مُّكَذِّبِينَ</span><br />\r\n<br />\r\n(நிச்சயமாக, உங்களில் (இந்தக் குர்ஆனை) பொய்ப்பிக்கக்கூடியவர்களும் இருக்கிறார்கள் என்பதை நாம் அறிவோம்.) அதாவது, இவ்வளவு விளக்கங்களுக்கும் தெளிவுபடுத்தல்களுக்கும் பிறகும், உங்களில் குர்ஆனை நிராகரிப்பவர்கள் இருப்பார்கள். பின்னர் அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَحَسْرَةٌ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْكَافِرِينَ</span><br />\r\n<br />\r\n(நிச்சயமாக அது (இந்தக் குர்ஆன்) நிராகரிப்பாளர்களுக்கு (மறுமை நாளில்) ஒரு கைசேதமாக (துயரமாக) இருக்கும்.) இப்னு ஜரீர் அவர்கள் கூறினார்கள்: \"நிச்சயமாக இந்த நிராகரிப்பானது மறுமை நாளில் நிராகரிப்பாளர்களுக்குப் பெரும் துயரமாக இருக்கும்.\" இதே போன்ற கருத்தைக் கத்தாதா (ரழி) அவர்களிடமிருந்தும் அவர் குறிப்பிட்டுள்ளார். 'அது' (it) என்ற பிரதிப்பெயர்ச்சொல் குர்ஆனைக் குறிப்பதாகவும் இருக்கலாம்; அவ்வாறாயின், குர்ஆனும் அதன் மீதான நம்பிக்கையுமே நிராகரிப்பாளர்களுக்குக் கைசேதமாக அமையும் என்று பொருள்படும். இது அல்லாஹ் கூறுவதைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">سَلَكْنَاهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قُلُوبِ</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span><br />\r\n<br />\r\n(இவ்வாறே நாம் அதனை (நிராகரிப்பை)க் குற்றவாளிகளின் இதயங்களில் நுழையச் செய்தோம். அவர்கள் அதனை நம்ப மாட்டார்கள்.) (<a href=\"qurandisp.php?sura=26&ayah=200\" class=\"link\">26:200</a>, 201) மேலும் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَحِيلَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَشْتَهُونَ</span><br />\r\n<br />\r\n(அவர்களுக்கும் அவர்கள் விரும்பியதற்கும் இடையில் ஒரு திரை ஏற்படுத்தப்படும்.) (<a href=\"qurandisp.php?sura=34&ayah=54\" class=\"link\">34:54</a>). எனவே, அல்லாஹ் இங்கு கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَحَقُّ</span> <span class=\"quran-arabic-font text-success\">الْيَقِينِ</span><br />\r\n<br />\r\n(நிச்சயமாக, இது (குர்ஆன்) முற்றிலும் உறுதியான சத்தியமாகும்.) அதாவது, எவ்விதச் சந்தேகமும், ஐயமும் அல்லது குழப்பமும் இல்லாத சரியான மற்றும் உண்மையான செய்தி. பின்னர் அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَسَبِّحْ</span> <span class=\"quran-arabic-font text-success\">بِاسْمِ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمِ</span><br />\r\n<br />\r\n(ஆகவே, மகத்துவமிக்க உமது இறைவனின் திருப்பெயரைப் போற்றித் துதிப்பீராக.) அதாவது, இந்த மகத்தான குர்ஆனை இறக்கி வைத்தவனைப் போற்றுவீராக. இது சூரா அல்-ஹாக்காவின் தஃப்சீர் விளக்கவுரையின் நிறைவாகும். எல்லாப் புகழும் அருளும் அல்லாஹ்வுக்கே உரியன.<br />\r\n<br />\r\n<br />\r\n<br />","text":"நபி (ஸல்) அவர்கள் அல்லாஹ்வின் மீது எதையேனும் இட்டுக்கட்டியிருந்தால், அல்லாஹ் அவர்களைத் தண்டித்திருப்பான்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nوَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ الأَقَاوِيلِ\n\r\n\n\r\n(அவர் நம்மீது சில கூற்றுகளை இட்டுக்கட்டியிருந்தால்,) அதாவது, \"நிராகரிப்பாளர்கள் வாதிடுவது போல முஹம்மது (ஸல்) அவர்கள் நம்மீது எதையேனும் இட்டுக்கட்டி, இந்தத் தூதுச்செய்தியில் எதையேனும் சேர்த்தோ அல்லது நீக்கியோ, அல்லது நாமே சொன்னதாகக் கூறித் தமக்காக எதையேனும் கற்பனை செய்து சொல்லியிருந்தால், நாம் நிச்சயமாக அவர்களைத் தண்டிப்பதில் விரைந்திருப்போம். நிச்சயமாக, முஹம்மது (ஸல்) அவர்கள் (நிராகரிப்பாளர்கள் கூறுவது போல்) இவற்றில் எதையும் செய்யவில்லை.\" எனவே அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nلأَخَذْنَا مِنْهُ بِالْيَمِينِ\n\r\n\n\r\n(நாம் நிச்சயமாக அவர்களை அவர்களுடைய வலது கையால் பிடித்திருப்போம்,) வலது கையால் பிடிப்பது மிகவும் வலிமையான பிடி என்பதால், \"நாம் அவர்களை வலது கையால் பிடித்திருப்போம்\" என்று இங்கே கூறப்பட்டுள்ளது.\n\r\n\n\r\nثُمَّ لَقَطَعْنَا مِنْهُ الْوَتِينَ\n\r\n\n\r\n(பின்னர் நாம் நிச்சயமாக அவர்களிடமிருந்து அல்-வதீனைத் துண்டித்திருப்போம்,) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அது (அல்-வதீன்) இதயத்தின் தமனியைக் குறிக்கும்; மேலும் அது இதயத்துடன் இணைக்கப்பட்டுள்ள ஒரு நரம்பாகும்.\" இக்ரிமா (ரழி), ஸயீத் பின் ஜுபைர் (ரழி), அல்-ஹகம், கத்தாதா (ரழி), அத்-தஹ்ஹாக் (ரழி), முஸ்லிம் அல்-பாத்தின் மற்றும் அபூ ஸக்ர் ஹுமைத் பின் ஸியாத் ஆகியோரும் இவ்வாறே கூறியுள்ளனர். முஹம்மது பின் கஅப் (ரழி) அவர்கள் கூறினார்கள்: \"அது (அல்-வதீன்) இதயம், அதன் இரத்தம் மற்றும் அதனைச் சுற்றியுள்ள பகுதியைக் குறிக்கும்.\" அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nفَمَا مِنكُم مِّنْ أَحَدٍ عَنْهُ حَاجِزِينَ\n\r\n\n\r\n(உங்களில் எவரும் அவரை விட்டும் (நம் தண்டனையைத்) தடுத்திருக்க முடியாது.) இதன் பொருள், \"நாம் அவர்களுக்கு இத்தகைய தண்டனையை அளிக்க விரும்பினால், உங்களில் எவராலும் நமக்கும் அவர்களுக்கும் இடையில் தடையாக வர முடியாது\" என்பதாகும். இதற்கெல்லாம் பின்னால் உள்ள கருத்து என்னவென்றால், அவர்கள் (முஹம்மது (ஸல்) அவர்கள்) உண்மையானவர், நேர்மையானவர் மற்றும் நேர்வழி பெற்றவர் என்பதாகும். ஏனெனில், அவர்கள் எதனைத் தெரிவிக்க வேண்டும் என்பதை அல்லாஹ்வே தீர்மானித்தான்; மேலும் அற்புதமான அற்புதங்கள் மற்றும் தெளிவான அத்தாட்சிகளைக் கொண்டு அல்லாஹ் அவர்களுக்கு உதவி புரிகிறான். பின்னர் அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nوَإِنَّهُ لَتَذْكِرَةٌ لِّلْمُتَّقِينَ\n\r\n\n\r\n(நிச்சயமாக, இது (குர்ஆன்) தக்வா (இறையச்சம்) உடையவர்களுக்கு ஒரு நினைவூட்டலாகும்.) அதாவது குர்ஆன். இது அல்லாஹ் பின்வருமாறு கூறுவதைப் போன்றது:\n\r\n\n\r\nقُلْ هُوَ لِلَّذِينَ ءَامَنُواْ هُدًى وَشِفَآءٌ وَالَّذِينَ لاَ يُؤْمِنُونَ فِى ءَاذَانِهِمْ وَقْرٌ وَهُوَ عَلَيْهِمْ عَمًى\n\r\n\n\r\n(கூறுவீராக: \"இது ஈமான் கொண்டவர்களுக்கு ஒரு வழிகாட்டியாகவும், ஒரு நிவாரணமாகவும் இருக்கிறது. நம்பிக்கை கொள்ளாதவர்களைப் பொறுத்தவரை, அவர்களின் காதுகளில் ஒரு செவிட்டுத்தன்மை இருக்கிறது; மேலும் அது (குர்ஆன்) அவர்களுக்குக் குருட்டுத்தன்மையாகும்.\") பின்னர் அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nوَإِنَّا لَنَعْلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ\n\r\n\n\r\n(நிச்சயமாக, உங்களில் (இந்தக் குர்ஆனை) பொய்ப்பிக்கக்கூடியவர்களும் இருக்கிறார்கள் என்பதை நாம் அறிவோம்.) அதாவது, இவ்வளவு விளக்கங்களுக்கும் தெளிவுபடுத்தல்களுக்கும் பிறகும், உங்களில் குர்ஆனை நிராகரிப்பவர்கள் இருப்பார்கள். பின்னர் அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nوَإِنَّهُ لَحَسْرَةٌ عَلَى الْكَافِرِينَ\n\r\n\n\r\n(நிச்சயமாக அது (இந்தக் குர்ஆன்) நிராகரிப்பாளர்களுக்கு (மறுமை நாளில்) ஒரு கைசேதமாக (துயரமாக) இருக்கும்.) இப்னு ஜரீர் அவர்கள் கூறினார்கள்: \"நிச்சயமாக இந்த நிராகரிப்பானது மறுமை நாளில் நிராகரிப்பாளர்களுக்குப் பெரும் துயரமாக இருக்கும்.\" இதே போன்ற கருத்தைக் கத்தாதா (ரழி) அவர்களிடமிருந்தும் அவர் குறிப்பிட்டுள்ளார். 'அது' (it) என்ற பிரதிப்பெயர்ச்சொல் குர்ஆனைக் குறிப்பதாகவும் இருக்கலாம்; அவ்வாறாயின், குர்ஆனும் அதன் மீதான நம்பிக்கையுமே நிராகரிப்பாளர்களுக்குக் கைசேதமாக அமையும் என்று பொருள்படும். இது அல்லாஹ் கூறுவதைப் போன்றது:\n\r\n\n\r\nكَذَلِكَ سَلَكْنَاهُ فِي قُلُوبِ الْمُجْرِمِينَ لاَ يُؤْمِنُونَ بِهِ\n\r\n\n\r\n(இவ்வாறே நாம் அதனை (நிராகரிப்பை)க் குற்றவாளிகளின் இதயங்களில் நுழையச் செய்தோம். அவர்கள் அதனை நம்ப மாட்டார்கள்.) (26:200, 201) மேலும் அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ\n\r\n\n\r\n(அவர்களுக்கும் அவர்கள் விரும்பியதற்கும் இடையில் ஒரு திரை ஏற்படுத்தப்படும்.) (34:54). எனவே, அல்லாஹ் இங்கு கூறுகிறான்,\n\r\n\n\r\nوَإِنَّهُ لَحَقُّ الْيَقِينِ\n\r\n\n\r\n(நிச்சயமாக, இது (குர்ஆன்) முற்றிலும் உறுதியான சத்தியமாகும்.) அதாவது, எவ்விதச் சந்தேகமும், ஐயமும் அல்லது குழப்பமும் இல்லாத சரியான மற்றும் உண்மையான செய்தி. பின்னர் அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nفَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ\n\r\n\n\r\n(ஆகவே, மகத்துவமிக்க உமது இறைவனின் திருப்பெயரைப் போற்றித் துதிப்பீராக.) அதாவது, இந்த மகத்தான குர்ஆனை இறக்கி வைத்தவனைப் போற்றுவீராக. இது சூரா அல்-ஹாக்காவின் தஃப்சீர் விளக்கவுரையின் நிறைவாகும். எல்லாப் புகழும் அருளும் அல்லாஹ்வுக்கே உரியன."}}};})(self);
